  ui_story_5072_50720201_30_dialog_content = "¿No me digas que no tienes dinero por la forma en que estás divagando?",
  ui_story_5072_50720201_31_dialog_content = "No... ¿A qué te refieres...",
  ui_story_5072_50720201_32_dialog_content = "Ya he gastado demasiado aliento en ti, mujer.",
