  ui_story_5072_50720201_41_dialog_content = "Tal vez podamos seguir haciendo negocios más tarde una vez que te hayas calmado.",
  ui_story_5072_50720201_42_dialog_content = "Ven, mi señora.",
  ui_story_5072_50720201_43_dialog_content = "¿Eh? Oh, cierto.",
  ui_story_5072_50720201_44_dialog_content = "Uh, perdón por eso...",
  ui_story_5072_50720201_45_dialog_content = "M-Mi actuación todavía no es lo suficientemente buena.",
  ui_story_5072_50720201_46_dialog_content = "Me equivoqué...",
  ui_story_5072_50720201_47_dialog_content = "No te preocupes, eso es de esperar.",
  ui_story_5072_50720201_48_dialog_content = "Si acaso, lo hiciste mejor de lo que pensaba.",
  ui_story_5072_50720201_49_dialog_content = "¡Y también me dio la oportunidad de meterme en mi papel!",
  ui_story_5072_50720201_50_dialog_content = "Gracias por salvarme...",
  ui_story_5072_50720201_51_dialog_content = "Pero una cosa es segura, tendremos que jugar duro con ese comerciante.",
  ui_story_5072_50720201_52_dialog_content = "Entonces, vayamos con tácticas que son más familiares para un mercenario en la recolección de la información que necesitamos.",
  ui_story_5072_50720201_53_dialog_content = "¿Sigue el dueño? ¡Quiero hablar de negocios!",
  ui_story_5072_50720201_54_dialog_content = "¿Quién es...? Eres tú, de más temprano en el día...",
  ui_story_5072_50720201_55_dialog_content = "¿Qué quieres? ¿Crees que me acobardaré porque vuelves y buscas problemas por la noche?",
  ui_story_5072_50720201_56_dialog_content = "¿Buscando problemas? ¿No dije que tal vez podamos hacer negocios más tarde?",
  ui_story_5072_50720201_57_dialog_content = "Incluso si no puedes entregar lo que queremos, ¿tal vez tenemos algo que estás buscando?",
  ui_story_5072_50720201_58_dialog_content = "¿Interesado en nuevos adornos de los talleres de Longzhou? Hechos por maestros artesanos, ya sabes.",
