  ui_story_5072_50720201_62_dialog_content = "¿Pájaro mecánico normal? Vamos, pensé que eras un experto.",
  ui_story_5072_50720201_63_dialog_content = "¿Por qué no echas un vistazo más de cerca y lo pruebas?",
  ui_story_5072_50720201_64_dialog_content = "¿Qué? De ninguna manera... Es... ¡Dios mío...!",
  ui_story_5072_50720201_65_dialog_content = "...",
  ui_story_5072_50720201_66_dialog_content = "El dueño está definitivamente distraído como la señorita Armilla había predicho.",
  ui_story_5072_50720201_67_dialog_content = "Mientras está ocupado con el pájaro mecánico...",
  ui_story_5072_50720201_68_dialog_content = "<color=#e8d9bb>Chunda, chunda—</color>",
  ui_story_5072_50720201_69_dialog_content = "Uf, entré.",
  ui_story_5072_50720201_70_dialog_content = "Como esperábamos, esconden sus secretos en el piso de arriba.",
  ui_story_5072_50720201_71_dialog_content = "Las colecciones en este almacenamiento...",
  ui_story_5072_50720201_72_dialog_content = "Antigüedades deliberadamente ocultas a la vista, probablemente destinadas para el mercado negro...",
  ui_story_5072_50720201_73_dialog_content = "Y las falsificaciones... Bueno, después de todo, él no es exactamente un empresario honesto.",
  ui_story_5072_50720201_74_dialog_content = "Sin errores esta vez. Permíteme asegurarme antes de informar a Armilla.",
  ui_story_5072_50720201_75_dialog_content = "¡Cuidado, no toques esos!",
  ui_story_5072_50720201_76_dialog_content = "¡¿...?!",
  ui_story_5072_50720201_77_dialog_content = "¡¿Quién es ese?!",
  ui_story_5072_50720201_78_dialog_content = "Espera, las antigüedades...",
  ui_story_5072_50720201_79_dialog_content = "<color=#e8d9bb>Clang—Clang—</color>",
  ui_story_5072_50720201_80_dialog_content = "¿Qué está pasando? ¿Por qué hay una presencia oscura alrededor de estos objetos...?",
  ui_story_5072_50720201_81_dialog_content = "<color=#e8d9bb>Clang—Clang—</color>",
  ui_story_5072_50720201_82_dialog_content = "Y se están moviendo... Las antigüedades se están moviendo.",
  ui_story_5072_50720201_83_dialog_content = "Siento hostilidad... ¿Quieren atacarme?",
  ui_story_5072_50720201_84_dialog_content = "No, la señorita Armilla todavía está abajo. No puedo luchar con todo aquí.",
  ui_story_5072_50720201_85_dialog_content = "¡Mejor prevenir que lamentar, y vivir para luchar otro día!",
  ui_story_5072_50720202_1_dialog_content = "Mira, el pico no solo es un gran masajeador, también puede abrir cáscaras de nueces.",
  ui_story_5072_50720202_2_dialog_content = "¡Qué maravilloso!",
  ui_story_5072_50720202_3_dialog_content = "¡Tengo que tenerlo! Solo di tu precio, cualquier precio...",
  ui_story_5072_50720202_4_dialog_content = "Para ser honesto, he soñado con un cascanueces como este durante mucho tiempo, así que...",
  ui_story_5072_50720202_5_dialog_content = "Ejem...",
  ui_story_5072_50720202_6_dialog_content = "¡Ups, olvidé por completo a mi Lady! Ella debe estar cansada de esperarme.",
  ui_story_5072_50720202_7_dialog_content = "Hablaremos más tarde si estás interesado.",
  ui_story_5072_50720202_8_dialog_content = "Se está haciendo tarde y mi señora necesita regresar. No puedo mantenerla despierta.",
  ui_story_5072_50720202_9_dialog_content = "Espera, ¿qué pasa con el pájaro mecánico...?",
  ui_story_5072_50720202_10_dialog_content = "No vendemos cosas buenas a comerciantes sucios como él. ¡Vamos, nos vamos!",
  ui_story_5072_50720202_11_dialog_content = "Por supuesto, mi dama. Solo estaba jugando con él. ¡No iba a conseguirlo por ningún precio!",
  ui_story_5072_50720202_12_dialog_content = "¿Me estabas tomando el pelo?",
  ui_story_5072_50720202_13_dialog_content = "¡No, se llama lo que va, vuelve!",
  ui_story_5072_50720202_14_dialog_content = "Adiós.",
  ui_story_5072_50720202_15_dialog_content = "Eso llevó un poco más de tiempo de lo que pensaba.",
  ui_story_5072_50720202_16_dialog_content = "¿Pasó algo inesperado?",
  ui_story_5072_50720202_17_dialog_content = "Así es.",
  ui_story_5072_50720202_18_dialog_content = "Encontré antigüedades y falsificaciones escondidas en el segundo piso.",
  ui_story_5072_50720202_19_dialog_content = "Pero estaban envueltos en un aura negra peculiar... ¡y hasta se movían!",
  ui_story_5072_50720202_20_dialog_content = "Estuvieron cerca de rodearme.",
  ui_story_5072_50720202_21_dialog_content = "Era como una trampa esperando por mí.",
  ui_story_5072_50720202_22_dialog_content = "¿Trampa? ¿Lo planeó él? No, no podría haberlo hecho.",
  ui_story_5072_50720202_23_dialog_content = "Entonces, ¿él no es el problema?",
  ui_story_5072_50720202_24_dialog_content = "No me pareció sospechoso ni intentó ocultar ningún motivo.",
  ui_story_5072_50720202_25_dialog_content = "Si lo hizo intencionalmente, lo habría sentido.",
  ui_story_5072_50720202_26_dialog_content = "Pero es bastante extraño. Objetos con un aura ominosa y que se mueven por sí mismos...",
  ui_story_5072_50720202_27_dialog_content = "Es como si estuvieran encantados o malditos y se activaran con tu presencia...",
  ui_story_5072_50720202_28_dialog_content = "¿Maldito...?!",
  ui_story_5072_50720202_29_dialog_content = "Tranquilo. La maldición de la que hablo se refiere a cómo la gente de Longzhou suplica a los dioses que traigan desastre a sus enemigos.",
  ui_story_5072_50720202_30_dialog_content = "En Longzhou, creemos que todo es consciente.",
  ui_story_5072_50720202_31_dialog_content = "Ya sean diablillos nacidos de la naturaleza o reliquias antiguas, todos tienen anima.",
  ui_story_5072_50720202_32_dialog_content = "A veces, son adorados y rezados, lo cual difiere enormemente de las costumbres aquí.",
  ui_story_5072_50720202_33_dialog_content = "Tomaré nota de eso en caso de que tenga algo que ver con tu maldición.",
  ui_story_5072_50720202_34_dialog_content = "Sabremos qué está pasando una vez que descubramos al cerebro detrás de estas vallas.",
  ui_story_5072_50720202_35_dialog_content = "Entiendo, la misión tiene prioridad.",
  ui_story_5072_50720202_36_dialog_content = "Además...",
  ui_story_5072_50720202_37_dialog_content = "¿Qué es?",
  ui_story_5072_50720202_38_dialog_content = "Oh, nada.",
  ui_story_5072_50720202_39_dialog_content = "(La señorita Armilla estaba ocupada hablando con el hombre y no pudo haberme advertido.)",
  ui_story_5072_50720202_40_dialog_content = "(Entonces, ¿de dónde vino la advertencia?)",
  ui_story_5072_50720202_41_dialog_content = "(O tal vez estaba escuchando cosas...)",
  ui_story_5072_50720301_1_dialog_content = "Lo siento, todavía no estoy acostumbrado a arreglarme.",
  ui_story_5072_50720301_2_dialog_content = "Está bien. Los accesorios y el peinado sí toman tiempo.",
  ui_story_5072_50720301_3_dialog_content = "Pero lo dominarás si practicas lo suficiente durante unos días.",
  ui_story_5072_50720301_4_dialog_content = "Estoy un poco preocupada.",
  ui_story_5072_50720301_5_dialog_content = "La reunión no salió bien. ¿El tendero nos verá hoy?",
  ui_story_5072_50720301_6_dialog_content = "Relájate, así es como suelen ir las conversaciones de negocios. He visto peores.",
  ui_story_5072_50720301_7_dialog_content = "Solo estamos tratando de averiguar si él podría arrojar alguna luz sobre su encuentro de anoche.",
  ui_story_5072_50720301_8_dialog_content = "El punto son los patrocinadores detrás de él, ¡así que no te pongas tenso!",
  ui_story_5072_50720301_9_dialog_content = "Entiendo.",
  ui_story_5072_50720301_10_dialog_content = "Muy bien, vamos entonces, mi señora.",
  ui_story_5072_50720301_11_dialog_content = "Nos encontramos de nuevo, señor.",
  ui_story_5072_50720301_12_dialog_content = "Bueno, si no es el pequeño alborotador de ayer...",
  ui_story_5072_50720301_13_dialog_content = "¿C-Cómo te atreves a hablarme así?",
  ui_story_5072_50720301_14_dialog_content = "Acabo de hacerlo. ¿Qué vas a hacer al respecto?",
  ui_story_5072_50720301_15_dialog_content = "Estaba bien anoche hasta que ustedes dos aparecieron y de alguna manera mi cuarto de almacenamiento se convirtió en un desastre!",
  ui_story_5072_50720301_16_dialog_content = "¡Los guardias también se desmayaron y no podían recordar lo que sucedió!",
  ui_story_5072_50720301_17_dialog_content = "Era como si estuvieran drogados por el... algo de Longzhou...",
  ui_story_5072_50720301_18_dialog_content = "¡Oye, no me digas que tú estás detrás de todo eso?!",
  ui_story_5072_50720301_19_dialog_content = "¡Qué grosero de tu parte sospechar de mí!",
  ui_story_5072_50720301_20_dialog_content = "Estaba contemplando intercambiar un favor de los Lins a los oficiales en Umbraton para una investigación exhaustiva para ti.",
  ui_story_5072_50720301_21_dialog_content = "¡Supongo que eso ya no es necesario!",
  ui_story_5072_50720301_22_dialog_content = "¡E-Espera, por favor ayúdame si tienes influencia!",
  ui_story_5072_50720301_23_dialog_content = "Soy un pequeño operador aquí. No puedo permitirme perder nada.",
  ui_story_5072_50720301_24_dialog_content = "Bueno, todo lo que tienes son falsificaciones, ¡y no tengo tiempo para eso!",
  ui_story_5072_50720301_25_dialog_content = "Si no quieres trabajar conmigo, alguien más lo hará.",
  ui_story_5072_50720301_26_dialog_content = "¡Me voy! ¡Adiós!",
  ui_story_5072_50720301_27_dialog_content = "Uf, se acabó.",
  ui_story_5072_50720301_28_dialog_content = "¿Mi desempeño obtuvo una calificación aprobatoria?",
  ui_story_5072_50720301_29_dialog_content = "¿Pasando? ¡Fue perfecto!",
  ui_story_5072_50720301_30_dialog_content = "Incluso yo estaba intimidado por ello, mi dama.",
  ui_story_5072_50720301_31_dialog_content = "Bueno, sentí que la confianza crecía a medida que me metía más en el papel.",
  ui_story_5072_50720301_32_dialog_content = "Antes de que te dieras cuenta, estaba diciendo cosas que normalmente no diría.",
  ui_story_5072_50720301_33_dialog_content = "<size=30>Afortunadamente, estoy en Twin Pavilions Bay...</size>",
  ui_story_5072_50720301_34_dialog_content = "<size=30>(Si los chicos de Umbraton lo escucharan... tendría que cavar un agujero y esconderme en un capullo de espinas.)</size>",
  ui_story_5072_50720301_35_dialog_content = "¿Por qué no aprovechamos y continuamos nuestros esfuerzos?",
  ui_story_5072_50720301_36_dialog_content = "Hay muchas tiendas en mi lista.",
  ui_story_5072_50720301_37_dialog_content = "Haremos preguntas y anotaremos las respuestas.",
  ui_story_5072_50720301_38_dialog_content = "Entonces puedes colarte dentro por la noche y confirmar si están diciendo la verdad o no.",
  ui_story_5072_50720301_39_dialog_content = "Sí, eso es más adecuado para mí.",
  ui_story_5072_50720301_40_dialog_content = "Vamos, estás cogiendo el truco de ser un socialité.",
  ui_story_5072_50720301_41_dialog_content = "Se requiere esfuerzo para charlar con los tenderos.",
  ui_story_5072_50720301_42_dialog_content = "Deberías ir de compras y disfrutar de las vistas con ese disfraz cuando tengas tiempo.",
  ui_story_5072_50720301_43_dialog_content = "¿Qué? Eh, eso está bien.",
  ui_story_5072_50720301_44_dialog_content = "¿Qué dije sobre estar tenso? ¿Incluso comiste la fruta que compraste ayer?",
  ui_story_5072_50720301_45_dialog_content = "No quería que se estropearan, así que tuve algunas naranjas.",
  ui_story_5072_50720301_46_dialog_content = "Para compensarlo, te invitaré a una especialidad de Longzhou cuando terminemos con todo esto.",
  ui_story_5072_50720301_47_dialog_content = "Eh, bueno.",
  ui_story_5072_50720301_48_dialog_content = "Esa es una orden de tu jefe.",
  ui_story_5072_50720301_49_dialog_content = "Vale, entonces eso me parece bien.",
  ui_story_5072_50720401_1_dialog_content = "Está bien, una irrupción exitosa esta noche.",
  ui_story_5072_50720401_2_dialog_content = "La señorita Armilla es ciertamente minuciosa en sus investigaciones...",
  ui_story_5072_50720401_3_dialog_content = "Dos canastas de dumplings de sopa, dos leches de soja y dos palitos de masa frita para llevar.",
  ui_story_5072_50720401_4_dialog_content = "Vaya, veo que eres un experto en especialidades de Longzhou.",
  ui_story_5072_50720401_5_dialog_content = "No exactamente. Estás respaldado por el famoso Gremio de la Concha Roja y eso te convierte en una franquicia conocida.",
  ui_story_5072_50720401_6_dialog_content = "Gracias por el reconocimiento. Permíteme obtener tu pedido para ti.",
  ui_story_5072_50720401_7_dialog_content = "Antes de que lo hagas, me pregunto si has escuchado algo interesante por el lado oeste?",
  ui_story_5072_50720401_8_dialog_content = "¡Mi dama está un poco aburrida y le gustaría escuchar algunas historias!",
  ui_story_5072_50720401_9_dialog_content = "¿Historias? Bueno, sí, la gente rica de allí ha estado hablando de ello todo el tiempo recientemente.",
  ui_story_5072_50720401_10_dialog_content = "Un coleccionista con antecedentes de Lumopolis se dedicó a comprar antigüedades de Longzhou.",
  ui_story_5072_50720401_11_dialog_content = "¡Supuestamente porque las reliquias contenían espíritus extranjeros!",
  ui_story_5072_50720401_12_dialog_content = "Pffffft—",
  ui_story_5072_50720401_13_dialog_content = "¿Pensó que conseguiría a una princesa extranjera al juntar todos los fragmentos?",
  ui_story_5072_50720401_14_dialog_content = "¡Loco, verdad? ¡Y se volvió loco hace solo unos días!",
  ui_story_5072_50720401_15_dialog_content = "¿Loco, dijiste? ¿Cómo exactamente?",
  ui_story_5072_50720401_16_dialog_content = "Resulta ser un amigo de mi jefe y vive en una gran mansión.",
  ui_story_5072_50720401_17_dialog_content = "Ni siquiera puedo echarle un vistazo cuando dejo comida en las entregas.",
  ui_story_5072_50720401_18_dialog_content = "Échale un vistazo si estás interesado. Puedo darte la dirección. Todos saben dónde está.",
  ui_story_5072_50720401_19_dialog_content = "Fantástico, aquí tienes un consejo para ti.",
  ui_story_5072_50720401_20_dialog_content = "¡Bien! Muchas gracias a los dos.",
  ui_story_5072_50720401_21_dialog_content = "Entonces, ¿qué es el Gremio de la Concha Roja?",
  ui_story_5072_50720401_22_dialog_content = "Uno de los huesos más duros de roer que visitamos antes.",
  ui_story_5072_50720401_23_dialog_content = "Los meseros en el lugar seguro que hablaron con mucha gente.",
  ui_story_5072_50720401_24_dialog_content = "Siempre puedo obtener de ellos la información que no puedo conseguir por mi cuenta.",
  ui_story_5072_50720401_25_dialog_content = "Cuando terminemos de comer, vamos a visitar al coleccionista de Lumopolis. Quizás tengamos un avance.",
  ui_story_5072_50720401_26_dialog_content = "Claro... Las empanadillas de sopa son deliciosas...",
  ui_story_5072_50720401_27_dialog_content = "¿Ya estás comiendo? ¿Cuándo lo sirvieron?",
  ui_story_5072_50720401_28_dialog_content = "Sin embargo, la visita a plena luz del día fue un fracaso. No pude verlo ni siquiera con mi identidad falsa...",
  ui_story_5072_50720401_29_dialog_content = "El hombre es excéntrico, de hecho.",
  ui_story_5072_50720401_30_dialog_content = "La mansión está cerca de una calle bulliciosa, pero emana una vibra ominosa y escalofriante...",
  ui_story_5072_50720401_31_dialog_content = "No...",
  ui_story_5072_50720401_32_dialog_content = "Oigo algo...",
  ui_story_5072_50720401_33_dialog_content = "No te acerques, malvado...",
  ui_story_5072_50720401_34_dialog_content = "¡Ese es el colector!",
  ui_story_5072_50720401_35_dialog_content = "No está en su sano juicio en absoluto... ¿Qué está tratando de decir?",
  ui_story_5072_50720401_36_dialog_content = "¡Espíritu maligno! ¡Es el espíritu maligno!",
  ui_story_5072_50720401_37_dialog_content = "Un espíritu maligno está rondando Twin Pavilions Bay, vagando...",
  ui_story_5072_50720401_38_dialog_content = "¡Si no tienes cuidado, perderás la cabeza!",
  ui_story_5072_50720401_39_dialog_content = "¡Ahhhhh!",
  ui_story_5072_50720401_40_dialog_content = "¡¿Qué está pasando?!",
  ui_story_5072_50720401_41_dialog_content = "...",
  ui_story_5072_50720401_42_dialog_content = "¡Todos los guardias han sido noqueados!",
  ui_story_5072_50720401_43_dialog_content = "...",
  ui_story_5072_50720401_44_dialog_content = "Y el colector también...",
  ui_story_5072_50720401_45_dialog_content = "Tú...",
  ui_story_5072_50720401_46_dialog_content = "¡¿Quién eres?!",
  ui_story_5072_50720401_47_dialog_content = "¡Estás sosteniendo un arma! ¿Eres el asesino?!",
  ui_story_5072_50720401_48_dialog_content = "...",
  ui_story_5072_50720401_49_dialog_content = "¡La aura oscura es la misma que la de las antigüedades malditas!",
  ui_story_5072_50720401_50_dialog_content = "¿Es este el espíritu maligno del que habló el coleccionista?",
  ui_story_5072_50720401_51_dialog_content = "(!!!)",
  ui_story_5072_50720401_52_dialog_content = "¡Tan rapido!",
  ui_story_5072_50720401_53_dialog_content = "Hay tantas sombras en la habitación...",
  ui_story_5072_50720401_54_dialog_content = "No, no solo sombras ordinarias... Se sentían hostiles, muy parecidas a...",
  ui_story_5072_50720401_55_dialog_content = "¡¿Energía de espada?!",
  ui_story_5072_50720401_56_dialog_content = "<color=#e8d9bb>¡Clang—Ka-thunk—!</color>",
  ui_story_5072_50720401_57_dialog_content = "¿¡Está intentando destruir todo aquí?! ¡De ninguna manera!",
  ui_story_5072_50720401_58_dialog_content = "Ja-",
  ui_story_5072_50720401_59_dialog_content = "¡Te pelearé!",
  ui_story_5072_50720402_1_dialog_content = "<color=#e8d9bb>¡Whoosh—!</color>",
  ui_story_5072_50720402_2_dialog_content = "...",
  ui_story_5072_50720402_3_dialog_content = "Silbido...",
  ui_story_5072_50720402_4_dialog_content = "No lo entiendo... Debería poder derribarlo con mi espada mágica.",
  ui_story_5072_50720402_5_dialog_content = "Pero estas sombras siguen apareciendo y reformándose después de cada corte como si no las hubiera golpeado en absoluto...",
  ui_story_5072_50720402_6_dialog_content = "Y se están acercando cada vez más...",
  ui_story_5072_50720402_7_dialog_content = "De alguna manera tengo que mantenerlos a raya.",
  ui_story_5072_50720402_8_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_5072_50720402_9_dialog_content = "Ay...",
  ui_story_5072_50720402_10_dialog_content = "Esta habitación está llena de cosas. Ya no hay más espacio para correr.",
  ui_story_5072_50720402_11_dialog_content = "Oh no...",
  ui_story_5072_50720402_12_dialog_content = "rugir—",
  ui_story_5072_50720402_13_dialog_content = "¡Su energía de espada me está constriñendo!",
  ui_story_5072_50720402_14_dialog_content = "Duele con todas las emociones y pensamientos negativos...",
  ui_story_5072_50720402_15_dialog_content = "Cálmate.",
  ui_story_5072_50720402_16_dialog_content = "¿Es la misma voz que me advirtió antes?",
  ui_story_5072_50720402_17_dialog_content = "Entonces no estaba escuchando cosas sino que en realidad...",
  ui_story_5072_50720402_18_dialog_content = "¡¿Mi espada?!",
  ui_story_5072_50720402_19_dialog_content = "Mantén la concentración. La visibilidad aquí es demasiado pobre para que puedas ver la verdad oculta por las sombras.",
  ui_story_5072_50720402_20_dialog_content = "¡No te preocupes por el aura negra. ¡Solo está ahí para distraerte!",
  ui_story_5072_50720402_21_dialog_content = "Tu objetivo está al final del todo.",
  ui_story_5072_50720402_22_dialog_content = "Salta y golpea. Yo trazaré el camino para ti.",
  ui_story_5072_50720402_23_dialog_content = "No tengo tiempo para reflexionar sobre todo lo que dijiste, pero...",
  ui_story_5072_50720402_24_dialog_content = "¡Lo tengo y confiaré en ti!",
  ui_story_5072_50720402_25_dialog_content = "(!!!)",
  ui_story_5072_50720402_26_dialog_content = "¡Lo hice! Y uno sólido también.",
  ui_story_5072_50720402_27_dialog_content = "...",
  ui_story_5072_50720402_28_dialog_content = "Las sombras se han disipado. Ahora bien, déjame ver quién eres en realidad.",
  ui_story_5072_50720402_29_dialog_content = "...",
  ui_story_5072_50720402_30_dialog_content = "¿Qué? ¿No es ese el servidor que nos contó la historia?",
  ui_story_5072_50720402_31_dialog_content = "Es solo un tipo promedio, ¿cómo podría ser tan duro...?",
  ui_story_5072_50720402_32_dialog_content = "Quizás sea su espada... Probablemente tenga poderes especiales como los míos.",
  ui_story_5072_50720402_33_dialog_content = "...",
  ui_story_5072_50720402_34_dialog_content = "Congélate.",
  ui_story_5072_50720402_35_dialog_content = "¡Aquí!",
  ui_story_5072_50720402_36_dialog_content = "¿Alguien está entrando...?",
  ui_story_5072_50720402_37_dialog_content = "¡Acabo de ver una figura extraña con una espada enorme entrar!",
  ui_story_5072_50720402_38_dialog_content = "Pero ahí es donde vive el coleccionista loco. Deberíamos dejarlo solo.",
  ui_story_5072_50720402_39_dialog_content = "No, si podemos resolver el caso, ¡probablemente seremos recompensados tanto por el Señor de la Ciudad como por el gremio!",
  ui_story_5072_50720402_40_dialog_content = "Esto no es bueno. Alguien está entrando justo ahora...",
  ui_story_5072_50720402_41_dialog_content = "Será malo si me ven.",
  ui_story_5072_50720402_42_dialog_content = "Debería ir e informar a la señorita Armilla.",
  ui_story_5072_50720501_1_dialog_content = "Señor, espero que pueda ofrecer una explicación adecuada para el Gremio de la Concha Roja.",
  ui_story_5072_50720501_2_dialog_content = "En los negocios, la integridad es primordial, sin excepciones.",
  ui_story_5072_50720501_3_dialog_content = "Pero ya sea lo que pasó anoche o mis anteriores consultas relacionadas con antigüedades...",
  ui_story_5072_50720501_4_dialog_content = "No has dicho ni una pizca de verdad, ¿qué significa eso?",
  ui_story_5072_50720501_5_dialog_content = "¿El Gremio de la Concha Roja mintió?",
  ui_story_5072_50720501_6_dialog_content = "Desde luego que sí. Afirmaron que el coleccionista desquiciado no tenía nada que ver con ellos cuando todo se trataba de ellos.",
  ui_story_5072_50720501_7_dialog_content = "Todo en la casa de la víctima fue comprado por ellos. Escuché que también enviaron al asesino.",
  ui_story_5072_50720501_8_dialog_content = "¡No, eso no es cierto en absoluto!",
  ui_story_5072_50720501_9_dialog_content = "El caso de anoche fue abrupto e inesperado. ¡Solo necesitamos tiempo para investigar!",
  ui_story_5072_50720501_10_dialog_content = "Está bien, en cuanto a la participación de Red Shell en el ataque...",
  ui_story_5072_50720501_11_dialog_content = "El Gremio Ziyun esperará tu investigación.",
  ui_story_5072_50720501_12_dialog_content = "Pero nos gustaría que explicaras las órdenes del mercado negro.",
  ui_story_5072_50720501_13_dialog_content = "Cuando visité hace unos días, dejaste claro que nunca te involucrarías en tales transacciones.",
  ui_story_5072_50720501_14_dialog_content = "Pero ahora que ha salido a la luz, ¿qué dices al respecto?",
  ui_story_5072_50720501_15_dialog_content = "¡Guau, de la sartén al fuego!",
  ui_story_5072_50720501_16_dialog_content = "¡Sabía que Red Shell tiene vínculos con el mercado negro!",
  ui_story_5072_50720501_17_dialog_content = "Por favor, todos, cálmense y tómenlo con calma. Se resolverá con el tiempo.",
  ui_story_5072_50720501_18_dialog_content = "Nos encargamos de esas antigüedades de Longzhou de origen desconocido.",
  ui_story_5072_50720501_19_dialog_content = "Pero todos sabemos que para triunfar en Umbraton y Twin Pavilions Bay, tienes que estrechar la mano de ambos lados.",
  ui_story_5072_50720501_20_dialog_content = "No es que me niegue a divulgar, pero las conexiones subterráneas no son algo que quieras hacer público...",
  ui_story_5072_50720501_21_dialog_content = "Lo hice por preocupación por la paz en Twin Pavilions Bay.",
  ui_story_5072_50720501_22_dialog_content = "¿Por la paz en la bahía? Más bien parece preocupación por tu propio negocio para mí.",
  ui_story_5072_50720501_23_dialog_content = "Pero nada de eso es importante para donde estamos ahora.",
  ui_story_5072_50720501_24_dialog_content = "Incluyendo a mi dama aquí, muchas personas vieron anoche que el asesino trabaja para ti.",
  ui_story_5072_50720501_25_dialog_content = "Si se descubre el asesinato-robo, no habrá lugar para tu gremio en esta ciudad.",
  ui_story_5072_50720501_26_dialog_content = "¡Oye, no seas tan precipitado ahora!",
  ui_story_5072_50720501_27_dialog_content = "El negocio del mercado negro sigue siendo negocio.",
  ui_story_5072_50720501_28_dialog_content = "Pero solo los bandidos saquearían y robarían de esa manera.",
  ui_story_5072_50720501_29_dialog_content = "¡De ninguna manera arruinaría el futuro de mi gremio por una ganancia tan pequeña!",
  ui_story_5072_50720501_30_dialog_content = "¿Estás diciendo la verdad?",
  ui_story_5072_50720501_31_dialog_content = "¡Lo juro por mi propia vida!",
  ui_story_5072_50720501_32_dialog_content = "No creo que tú correrías ese riesgo tampoco. De hecho, sospecho que el tipo está trabajando secretamente para alguien más.",
  ui_story_5072_50720501_33_dialog_content = "¿Así que has estado sacándome información todo este tiempo?!",
  ui_story_5072_50720501_34_dialog_content = "No te desvíes. Volveremos a cómo me mentiste.",
  ui_story_5072_50720501_35_dialog_content = "Sin embargo, averiguar quién está pagando al tipo será beneficioso para ambos.",
  ui_story_5072_50720501_36_dialog_content = "Él es solo un empleado promedio. No veo por qué alguien querría comprar su lealtad.",
  ui_story_5072_50720501_37_dialog_content = "Entonces solo queda una posibilidad.",
  ui_story_5072_50720501_38_dialog_content = "¿Qué es eso?",
  ui_story_5072_50720501_39_dialog_content = "Algunas de las reliquias que circulan en el mercado negro son poderosos artefactos que podrían controlar la mente de quien los sostenga.",
  ui_story_5072_50720501_40_dialog_content = "Después de todo, ese tipo luchó como un campeón mundial con una espada... Oh, y otra cosa.",
  ui_story_5072_50720501_41_dialog_content = "¿Escuché que el joven maestro de tu gremio también presenció al asesino anoche?",
  ui_story_5072_50720501_42_dialog_content = "¿Cuáles son las probabilidades de que él simplemente estuviera cerca cuando uno de sus trabajadores estaba cometiendo un delito?",
  ui_story_5072_50720501_43_dialog_content = "Es difícil no oler algo sospechoso en eso.",
  ui_story_5072_50720501_44_dialog_content = "¡Oye, deja de acusar a la gente sin pruebas!",
  ui_story_5072_50720501_45_dialog_content = "Fue a un bar con unos amigos y simplemente se topó con él en su camino de regreso.",
  ui_story_5072_50720501_46_dialog_content = "Si lo llevamos un paso más allá, ¿no haría eso a tu dama también una sospechosa?",
  ui_story_5072_50720501_47_dialog_content = "Oh, esa es una nueva teoría. ¿Por qué no me explicas cómo?",
  ui_story_5072_50720501_48_dialog_content = "Es normal que nuestro joven maestro, bastante extrovertido, salga a beber por la noche.",
  ui_story_5072_50720501_49_dialog_content = "Pero, ¿qué estaba haciendo su dama fuera en lugar de quedarse en casa?",
  ui_story_5072_50720501_50_dialog_content = "¡En ese sentido, su presencia y testimonio en realidad la convierten en la principal sospechosa!",
  ui_story_5072_50720501_51_dialog_content = "¿No me digas que todo esto es un montaje de tu gremio para arruinar nuestro nombre?",
  ui_story_5072_50720501_52_dialog_content = "¿Sabes algo sobre la dama del gremio Ziyun?",
  ui_story_5072_50720501_53_dialog_content = "No. Pero dado lo que se acaba de decir, podría haber algo peculiar en ella.",
  ui_story_5072_50720501_54_dialog_content = "Solo me he ido por un corto tiempo y ya me están acusando.",
  ui_story_5072_50720501_55_dialog_content = "¿Me estás llamando sospechoso?",
  ui_story_5072_50720501_56_dialog_content = "¡Vaya, la presencia... Solo podría ser la de una dama con clase!",
  ui_story_5072_50720501_57_dialog_content = "¡Es una suposición razonable!",
  ui_story_5072_50720501_58_dialog_content = "¿Por qué no haces una encuesta y ves si eso fue justo o no?",
  ui_story_5072_50720501_59_dialog_content = "Por supuesto. Cualquiera, por favor adelántese si también sospecha de mí.",
  ui_story_5072_50720501_60_dialog_content = "...",
  ui_story_5072_50720501_61_dialog_content = "Dado que no hay más comentarios, describiré mi encuentro de la noche anterior de nuevo.",
  ui_story_5072_50720501_62_dialog_content = "A diferencia del joven maestro que se agacha y se esconde, reacio a testificar.",
  ui_story_5072_50720501_63_dialog_content = "¿Por qué tú...? Bien, ¿por qué no te explicas entonces?",
  ui_story_5072_50720501_64_dialog_content = "Primero, vine a Twin Pavilions Bay para buscar reliquias familiares perdidas, por lo que fue insuficiente pasar por los canales normales.",
  ui_story_5072_50720501_65_dialog_content = "Pero las noches en la Bahía ofrecían una multitud más variada de lo que imaginaba...",
  ui_story_5072_50720501_66_dialog_content = "Finalmente localizamos al coleccionista con gran esfuerzo solo para que nos negaran la entrada, obligándonos a vigilar la residencia.",
  ui_story_5072_50720501_67_dialog_content = "Y terminamos teniendo problemas con el Anfitrión de Vilanor, junto con acusaciones infundadas de personas sombrías como tú.",
  ui_story_5072_50720501_68_dialog_content = "¿No hay ley en Twin Pavilions Bay?!",
  ui_story_5072_50720501_69_dialog_content = "...",
  ui_story_5072_50720501_70_dialog_content = "En cuanto a la aterradora aparición del Anfitrión de Vilanor...",
  ui_story_5072_50720501_71_dialog_content = "Toma en serio mis advertencias y no me culpes por no haberte advertido con anticipación.",
  ui_story_5072_50720502_1_dialog_content = "Y eso es todo lo que ocurrió en mi encuentro con él.",
  ui_story_5072_50720502_2_dialog_content = "No dudes en hacer cualquier pregunta que tengas ahora.",
  ui_story_5072_50720502_3_dialog_content = "Pero no escucharé dudas nuevamente después de hoy, o habrá consecuencias.",
  ui_story_5072_50720502_4_dialog_content = "...",
  ui_story_5072_50720502_5_dialog_content = "Entonces, ¿hay algún problema más que te gustaría discutir?",
  ui_story_5072_50720502_6_dialog_content = "Bueno, fuiste claro y creíble. No puedo discernir ningún agujero en tu historia por ahora.",
  ui_story_5072_50720502_7_dialog_content = "Parece que todos los gremios deberían aprender de esto y estar atentos al Anfitrión de Vilanor.",
  ui_story_5072_50720502_8_dialog_content = "Pero...",
  ui_story_5072_50720502_9_dialog_content = "Di lo que piensas.",
  ui_story_5072_50720502_10_dialog_content = "Veo que has estado cargando una funda de instrumento musical contigo, y obviamente es voluminosa e incómoda.",
  ui_story_5072_50720502_11_dialog_content = "May ¿Puedo preguntar por qué siempre lo llevas contigo?",
  ui_story_5072_50720502_12_dialog_content = "!",
  ui_story_5072_50720502_13_dialog_content = "...",
  ui_story_5072_50720502_14_dialog_content = "¿Por qué te andas por las ramas?",
  ui_story_5072_50720502_15_dialog_content = "¡Cuando todavía tienes dudas sobre mí!",
  ui_story_5072_50720502_16_dialog_content = "Soy de Longzhou, y tales artículos elegantes son una necesidad para los socialités que viajan por Longzhou.",
  ui_story_5072_50720502_17_dialog_content = "Además de los asuntos familiares, también esperaba conocer e intercambiar ideas con amantes de la música locales.",
  ui_story_5072_50720502_18_dialog_content = "¡Quién iba a saber que, por muy acogedora que pareciera Twin Pavilions Bay, no había lugar para mi instrumento musical!",
  ui_story_5072_50720502_19_dialog_content = "¡Si deseas inspeccionar, te lo entregaré!",
  ui_story_5072_50720502_20_dialog_content = "Lo siento por dudar de ti.",
  ui_story_5072_50720502_21_dialog_content = "¿Cómo puedo seguir sospechando cuando te has explicado tan claramente?",
  ui_story_5072_50720502_22_dialog_content = "Por favor, perdona mis acciones. May pronto alcanzas tus metas.",
  ui_story_5072_50720502_23_dialog_content = "Uf... Me alegro de que eso haya terminado.",
  ui_story_5072_50720502_24_dialog_content = "Perfección, absoluta perfección. Maravilloso trabajo, Arrie.",
  ui_story_5072_50720502_25_dialog_content = "Mi corazón se saltó un latido cuando ofreciste dejarle revisar el caso.",
  ui_story_5072_50720502_26_dialog_content = "Hiciste una decisión valiente.",
  ui_story_5072_50720502_27_dialog_content = "Bueno, eso no es lo que estaba pensando.",
  ui_story_5072_50720502_28_dialog_content = "Contaba con que él se rindiera una vez que descubriera que no podía mover el caso.",
  ui_story_5072_50720502_29_dialog_content = "Eso también es cierto.",
  ui_story_5072_50720502_30_dialog_content = "Sin embargo, dada la información que acabamos de recibir, tengo una corazonada de qué hacer a continuación.",
  ui_story_5072_50720502_31_dialog_content = "Nos dividiremos. Tú sigue buscando pistas en el distrito de negocios.",
  ui_story_5072_50720502_32_dialog_content = "En cuanto a mí, visitaré a algunos viejos amigos e intentaré desenterrar historias sobre el Anfitrión de Vilanor.",
  ui_story_5072_50720502_33_dialog_content = "Entonces, resolveremos el resto después de que nos volvamos a encontrar.",
  ui_story_5072_50720502_34_dialog_content = "Claro. Haré lo mejor que pueda.",
  ui_story_5072_50720503_1_dialog_content = "Oye, adivino, tu lectura estuvo muy desviada.",
  ui_story_5072_50720503_2_dialog_content = "Me dijiste que se avecinaban problemas hace unos días, pero terminé ganando algo de dinero.",
  ui_story_5072_50720503_3_dialog_content = "¿No garantizaste que estaría bien o me devolverías mi dinero? ¡Quiero un reembolso!",
  ui_story_5072_50720503_4_dialog_content = "Vamos, señor, no tenga tanta prisa.",
  ui_story_5072_50720503_5_dialog_content = "Si recuerdo correctamente, tu lectura no fue exactamente favorable. ¿Tigre Yang y Cerdo Yin, verdad?",
  ui_story_5072_50720503_6_dialog_content = "¿Todavía recuerdas eso?",
  ui_story_5072_50720503_7_dialog_content = "Desde luego. Indica un mal presagio.",
  ui_story_5072_50720503_8_dialog_content = "Las pequeñas ganancias que obtuviste... ¿Vinieron de una inversión?",
  ui_story_5072_50720503_9_dialog_content = "El escaso retorno fue solo un símbolo a cambio de tu vasta fortuna. Procede con precaución, no sea que te encuentres despojado de todo.",
  ui_story_5072_50720503_10_dialog_content = "¡Pierde, pierde!",
  ui_story_5072_50720503_11_dialog_content = "¡Todo, todo!",
  ui_story_5072_50720503_12_dialog_content = "¡Esos dos cuervos tuyos son malos presagios, igual que tú!",
  ui_story_5072_50720503_13_dialog_content = "Aunque también admito que pueden ser molestos, en realidad son estorninos, no cuervos.",
  ui_story_5072_50720503_14_dialog_content = "Bien, adivino, tu lectura puede estar equivocada, pero eres bastante bueno contando historias.",
  ui_story_5072_50720503_15_dialog_content = "El cuento que contaste sobre la camarera que se convirtió en la reina del reino submarino fue bonito. ¿Qué tal otro?",
  ui_story_5072_50720503_16_dialog_content = "Está bien, tengo otra. Se trata de un espadachín maldito.",
  ui_story_5072_50720503_17_dialog_content = "Todos, reúnanse y por favor déjenme una moneda o dos si pueden.",
  ui_story_5072_50720503_18_dialog_content = "Había una vez, un espadachín maldito...",
  ui_story_5072_50720503_19_dialog_content = "¡Quien era anémica, sufría de crecimientos espinosos, pero empuñaba una espada enorme!",
  ui_story_5072_50720503_20_dialog_content = "La hoja podría derrotar a cualquier demonio y vencer a cualquier enemigo.",
  ui_story_5072_50720503_21_dialog_content = "El espadachín viajó a lo largo del río de oro, sin buscar ni fortuna ni fama...",
  ui_story_5072_50720503_22_dialog_content = "Pero en una búsqueda obstinada por romper todo tipo de extrañas maldiciones.",
  ui_story_5072_50720503_23_dialog_content = "Porque ella creía que solo rompiendo todas las maldiciones del mundo podría encontrar una manera de salvarse a sí misma.",
  ui_story_5072_50720503_24_dialog_content = "Y ahora, ese espadachín ha llegado a Twin Pavilions Bay en la desembocadura del Río de Oro.",
  ui_story_5072_50720503_25_dialog_content = "¿Vencerá ella a la maldición y se liberará a sí misma?",
  ui_story_5072_50720503_26_dialog_content = "¡Hasta la próxima!",
  ui_story_5072_50720503_27_dialog_content = "¡Oye tú, no te detengas a mitad de camino!",
  ui_story_5072_50720503_28_dialog_content = "¡Sí!",
  ui_story_5072_50720503_29_dialog_content = "Bueno, si quieres más, creo que necesitaré un poco de motivación monetaria.",
  ui_story_5072_50720503_30_dialog_content = "¡Monetario, monetario!",
  ui_story_5072_50720503_31_dialog_content = "¡Motivación, motivación!",
  ui_story_5072_50720503_32_dialog_content = "¿Quieres dinero por eso? Me largo de aquí.",
  ui_story_5072_50720503_33_dialog_content = "¿Luchador de espada maldito?",
  ui_story_5072_50720503_34_dialog_content = "¿No es eso lo que ha estado pasando últimamente en este pueblo?",
  ui_story_5072_50720503_35_dialog_content = "¿Estás intentando vender la historia como si fuera tuya? ¡Ni en sueños!",
  ui_story_5072_50720503_36_dialog_content = "No, eso no es. ¿No me pidieron todos que contara una historia?",
  ui_story_5072_50720503_37_dialog_content = "Pensé que el Anfitrión de Vilanor era lo suficientemente grotesco como para asustar a todos.",
  ui_story_5072_50720503_38_dialog_content = "¿Cómo es que lo hiciste sonar como un cuento heroico? Solo se te permite cierta libertad creativa, ya sabes.",
  ui_story_5072_50720503_39_dialog_content = "Suspiro, es una delgada línea entre el bien y el mal.",
  ui_story_5072_50720503_40_dialog_content = "El espadachín puede parecer malvado hoy a tus ojos, pero puede convertirse en un héroe mañana.",
  ui_story_5072_50720503_41_dialog_content = "Fuera del camino... ¡Tú! ¿Quién te dio permiso para montar tu tienda aquí?",
  ui_story_5072_50720503_42_dialog_content = "Vamos, solo estoy tratando de ganarme la vida aquí. ¿Por qué no puedes dejarme en paz?",
  ui_story_5072_50720503_43_dialog_content = "En primer lugar, es ilegal que montes un puesto aquí.",
  ui_story_5072_50720503_44_dialog_content = "En segundo lugar, estamos colocando un cartel de buscado aquí y eso es la prioridad.",
  ui_story_5072_50720503_45_dialog_content = "¡Lárgate si sabes lo que es mejor para ti!",
  ui_story_5072_50720503_46_dialog_content = "Lo tengo. Pero déjame darte una lectura sobre esta recompensa antes de irme.",
  ui_story_5072_50720503_47_dialog_content = "Hmm, Perro Yin y Cabra Yin. Me temo que la persona en el cartel no es a quien deberías estar buscando.",
  ui_story_5072_50720503_48_dialog_content = "¡Esto no te incumbe!",
  ui_story_5072_50720503_49_dialog_content = "Bien, bien, veo que ninguna buena acción queda sin castigo. Adiós, entonces.",
  ui_story_5072_50720601_1_dialog_content = "Las calles del lado este parecen más concurridas de lo habitual hoy.",
  ui_story_5072_50720601_2_dialog_content = "Qué es esto...?",
  ui_story_5072_50720601_3_dialog_content = "¿Un cartel de búsqueda para el anfitrión de Vilanor?!",
  ui_story_5072_50720601_4_dialog_content = "No es de extrañar que la gente haya estado hablando de alguien con una espada grande y extraña...",
  ui_story_5072_50720601_5_dialog_content = "Tengo que ser más cuidadoso y asegurarme de que mi espada mágica no sea vista...",
  ui_story_5072_50720601_6_dialog_content = "Por suerte tengo el caso. Siempre y cuando actúe con naturalidad, nadie debería sospechar nada...",
  ui_story_5072_50720601_7_dialog_content = "¡Cuidado, Arrie, alguien se acerca rápidamente!",
  ui_story_5072_50720601_8_dialog_content = "¡¿Qué?!",
  ui_story_5072_50720601_9_dialog_content = "¡Cómo te atreves a acosar a una dama a plena luz del día!",
  ui_story_5072_50720601_10_dialog_content = "¿No hay ley en Twin Pavilions Bay?",
  ui_story_5072_50720601_11_dialog_content = "¡Ahórrame, jovencita, ahórrame!",
  ui_story_5072_50720601_12_dialog_content = "¿Ah?",
  ui_story_5072_50720601_13_dialog_content = "¡N-No tengo ninguna malicia en absoluto!",
  ui_story_5072_50720601_14_dialog_content = "Escuché a los miembros del gremio hablar sobre lo hábil que es la señora Ziyun como músico...",
  ui_story_5072_50720601_15_dialog_content = "Presumí que debes ser una dama elegante, así que pensé en ofrecerte el servicio de mi taller.",
  ui_story_5072_50720601_16_dialog_content = "¡Retrocederé en este momento si te he ofendido!",
  ui_story_5072_50720601_17_dialog_content = "(Parece lo suficientemente promedio para ser un comerciante.)",
  ui_story_5072_50720601_18_dialog_content = "(Pero mi espada nunca se ha equivocado, así que debería preguntar.)",
  ui_story_5072_50720601_19_dialog_content = "¿Es él realmente solo un comerciante?",
  ui_story_5072_50720601_20_dialog_content = "Bueno...",
  ui_story_5072_50720601_21_dialog_content = "Es posible que él también sea un ladrón.",
  ui_story_5072_50720601_22_dialog_content = "De todos modos, siento cierta hostilidad pero no una gran amenaza. Puedes estar tranquilo.",
  ui_story_5072_50720601_23_dialog_content = "Uf...",
  ui_story_5072_50720601_24_dialog_content = "Últimamente están buscando al Anfitrión de Vilanor, así que debemos tener cuidado.",
  ui_story_5072_50720601_25_dialog_content = "Has estado a mi lado todo el tiempo, espada mágica, así que intenta no asustarme.",
  ui_story_5072_50720601_26_dialog_content = "Tienes razón, Arrie.",
  ui_story_5072_50720601_27_dialog_content = "Pero mis habilidades son algo limitadas dentro de este caso, lo que también afecta mi juicio.",
  ui_story_5072_50720601_28_dialog_content = "No fue mi intención causar una falsa alarma. Espero que lo entiendas...",
  ui_story_5072_50720601_29_dialog_content = "Lo hago. Probablemente no se sienta bien mentir dentro de un confinamiento oscuro, imagino.",
  ui_story_5072_50720601_30_dialog_content = "Sin embargo, todavía no puedo creer que incluso ahora...",
  ui_story_5072_50720601_31_dialog_content = "Hemos estado juntos prácticamente toda mi vida.",
  ui_story_5072_50720601_32_dialog_content = "¿Quién podría haber pensado que la silenciosa espada mágica de repente hablaría?",
  ui_story_5072_50720601_33_dialog_content = "Bueno...",
  ui_story_5072_50720601_34_dialog_content = "Siempre te he imaginado como distante y solemne.",
  ui_story_5072_50720601_35_dialog_content = "Hasta que empezaste a hablar y realmente me hiciste sentir que no eras la espada que conocía.",
  ui_story_5072_50720601_36_dialog_content = "Pero más bien un amigo que siempre está cuidando de mí.",
  ui_story_5072_50720601_37_dialog_content = "Sobre eso... La habilidad y la personalidad no siempre coinciden.",
  ui_story_5072_50720601_38_dialog_content = "Como un espíritu de la espada recientemente despertado, quizás fui influenciado por ti.",
  ui_story_5072_50720601_39_dialog_content = "¿Yo? De ninguna manera, no soy tan poderoso. Eres tú quien ha tenido un mayor impacto en mí.",
  ui_story_5072_50720601_40_dialog_content = "No, para mí, de hecho eres tan poderoso.",
  ui_story_5072_50720601_41_dialog_content = "Porque todo lo que sé, lo aprendí de ti.",
  ui_story_5072_50720601_42_dialog_content = "Mi propósito es informarte todo sobre esta espada y ayudarte a ver el mundo desde su perspectiva.",
  ui_story_5072_50720601_43_dialog_content = "Antes, solo podía observar. ¡Pero ahora, finalmente puedo hablar y ayudarte!",
  ui_story_5072_50720601_44_dialog_content = "¡Espero que podamos seguir confiando el uno en el otro y buscar esperanza juntos!",
  ui_story_5072_50720601_45_dialog_content = "Vaya, nunca pensé que llegaría el día en que escucharía palabras de aliento de mi espada mágica...",
  ui_story_5072_50720601_46_dialog_content = "Gracias. Me siento mucho mejor ahora. El sentimiento es mutuo...",
  ui_story_5072_50720601_47_dialog_content = "<size=45>¡Alto, ladrón!</size>",
  ui_story_5072_50720601_48_dialog_content = "¡¿?!",
  ui_story_5072_50720601_49_dialog_content = "¿No es ese el tipo del que dijiste que tuviera cuidado antes?",
  ui_story_5072_50720601_50_dialog_content = "Realmente es un ladrón... Buena llamada.",
  ui_story_5072_50720601_51_dialog_content = "En realidad, fue solo un comentario casual...",
  ui_story_5072_50720601_52_dialog_content = "¿Entonces qué debemos hacer ahora...?",
  ui_story_5072_50720601_53_dialog_content = "Intentó robarme y probablemente te estaba apuntando a ti.",
  ui_story_5072_50720601_54_dialog_content = "No podemos dejar pasar eso, así que vamos a atraparlo, por supuesto.",
  ui_story_5072_50720601_55_dialog_content = "De acuerdo, vamos.",
  ui_story_5072_50720601_56_dialog_content = "Está lleno aquí. Puedo manejar esto yo mismo.",
  ui_story_5072_50720601_57_dialog_content = "Solo es un ladrón, después de todo. No pasé todos estos años como mercenario en vano...",
  ui_story_5072_50720601_58_dialog_content = "Así que siéntate y observa... Eh, siéntate y percibe lo que voy a hacer!",
  ui_story_5072_50720602_1_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5072_50720602_2_dialog_content = "¿No te dijeron que te detuvieras?",
  ui_story_5072_50720602_3_dialog_content = "Eres tú, la señora con la que me tropecé... No creo que tengamos un rencor entre nosotros.",
  ui_story_5072_50720602_4_dialog_content = "Entonces, ¿no puedes simplemente dejarme ir, viendo que esta es mi primera ofensa?",
  ui_story_5072_50720602_5_dialog_content = "Solo la gente puede decir si esta es tu primera vez.",
  ui_story_5072_50720602_6_dialog_content = "Además, estoy bastante seguro de que intentabas robarme en aquel entonces.",
  ui_story_5072_50720602_7_dialog_content = "No soy el tipo de persona que perdona a todos.",
  ui_story_5072_50720602_8_dialog_content = "Oye, ¿no es ese el ladrón que ha estado rondando durante días?",
  ui_story_5072_50720602_9_dialog_content = "Estúpido ladrón, ¡vamos a ver qué tan rápido puedes correr ahora!",
  ui_story_5072_50720602_10_dialog_content = "Muchas gracias, señorita.",
  ui_story_5072_50720602_11_dialog_content = "No lo menciones. Solo estoy haciendo lo que debería hacer.",
  ui_story_5072_50720602_12_dialog_content = "¡Oye, mira, el ladrón ha sido atrapado, gracias a la dama de Longzhou!",
  ui_story_5072_50720602_13_dialog_content = "¡Parece demasiado pequeña y delicada para ser una luchadora tan buena!",
  ui_story_5072_50720602_14_dialog_content = "mmm...",
  ui_story_5072_50720602_15_dialog_content = "(La multitud se está haciendo más grande y estoy empezando a sentirme un poco...)",
  ui_story_5072_50720602_16_dialog_content = "¡Como muestra de mi gratitud, me gustaría invitarte a mi tienda!",
  ui_story_5072_50720602_17_dialog_content = "Te serviré el mejor té que tengo...",
  ui_story_5072_50720602_18_dialog_content = "¡Ay!",
  ui_story_5072_50720602_19_dialog_content = "¡¿Quién me acaba de pinchar?!",
  ui_story_5072_50720602_20_dialog_content = "¿Qué estás diciendo? Nadie te tocó. ¡La dama es la única a tu lado!",
  ui_story_5072_50720602_21_dialog_content = "Está bien. No me quedaré. Deberías entregar al ladrón a la Guardia de la Ciudad...",
  ui_story_5072_50720602_22_dialog_content = "T-Tengo asuntos urgentes que atender, así que debo irme.",
  ui_story_5072_50720602_23_dialog_content = "Oye, espera, jovencita...",
  ui_story_5072_50720602_24_dialog_content = "¡Adiós!",
  ui_story_5072_50720602_25_dialog_content = "Uf...",
  ui_story_5072_50720602_26_dialog_content = "Estoy tan acostumbrado a este disfraz, que he olvidado las espinas en mí.",
  ui_story_5072_50720602_27_dialog_content = "Debo recordar mantener distancia de los demás.",
  ui_story_5072_50720602_28_dialog_content = "Lo siento...",
  ui_story_5072_50720602_29_dialog_content = "¿Eh? ¿Por qué te disculpas, Espada Mágica?",
  ui_story_5072_50720602_30_dialog_content = "Las espinas son mi culpa por no encontrar otra forma de curarte.",
  ui_story_5072_50720602_31_dialog_content = "Eso cuenta como negligencia de mi parte como espíritu de la espada, ¿verdad?",
  ui_story_5072_50720602_32_dialog_content = "No, ¿cómo puede ser tu culpa?",
  ui_story_5072_50720602_33_dialog_content = "¡Por favor, no te culpes a ti mismo!",
  ui_story_5072_50720602_34_dialog_content = "Las espinas salvaron mi vida y no me trajeron sufrimiento adicional... No tengo nada de qué quejarme.",
  ui_story_5072_50720602_35_dialog_content = "Solo quiero romper la maldición y tranquilizar a mi familia.",
  ui_story_5072_50720602_36_dialog_content = "Arrie...",
  ui_story_5072_50720602_37_dialog_content = "Y mira, incluso el problema de no poder usar vestidos bonitos no es un problema en Twin Pavilions Bay.",
  ui_story_5072_50720602_38_dialog_content = "Sí, el vestido te queda muy bien.",
  ui_story_5072_50720602_39_dialog_content = "Tú también, ¿Espada Mágica...? Bueno, basta de eso.",
  ui_story_5072_50720602_40_dialog_content = "(Francamente, a mí también me gusta así...)",
  ui_story_5072_50720602_41_dialog_content = "Ahora no es el momento de disfrutar la vida de una socialité. Tenemos que ir a encontrarnos con la señorita Armilla antes de que lleguemos tarde.",
  ui_story_5072_50720602_42_dialog_content = "Como mercenario, debo permanecer alerta en todo momento.",
  ui_story_5072_50720701_1_dialog_content = "Estoy por aquí, Arrie.",
  ui_story_5072_50720701_2_dialog_content = "¡¿?!",
  ui_story_5072_50720701_3_dialog_content = "¡Señorita Armilla! Uf, gracias a Dios, pensé que iba a llegar tarde.",
  ui_story_5072_50720701_4_dialog_content = "Está bien. Acabo de llegar yo mismo, y además con buenas noticias.",
  ui_story_5072_50720701_5_dialog_content = "Todo gracias a las pistas que conseguiste.",
  ui_story_5072_50720701_6_dialog_content = "¿Te refieres al Anfitrión de Vilanor?",
  ui_story_5072_50720701_7_dialog_content = "Sí. Lo que vale la pena celebrar es el hecho de que he descubierto el mayor misterio que lo rodea.",
  ui_story_5072_50720701_8_dialog_content = "Específicamente, cómo un camarero normal podría ser demasiado poderoso para que puedas manejarlo.",
  ui_story_5072_50720701_9_dialog_content = "¡La espada es la razón de todo esto!",
  ui_story_5072_50720701_10_dialog_content = "Los miembros de Red Shell dijeron que habían visto la espada antes. Es una hoja exquisita de Longzhou.",
  ui_story_5072_50720701_11_dialog_content = "¡La espada está definitivamente encantada y es precisamente lo que quiero recuperar!",
  ui_story_5072_50720701_12_dialog_content = "Esta historia también refleja cómo los engranajes se interconectan dentro de un dispositivo...",
  ui_story_5072_50720701_13_dialog_content = "¿Una espada arcana?",
  ui_story_5072_50720701_14_dialog_content = "Pero, ¿no requeriría eso una alta competencia del usuario para manejarlo?",
  ui_story_5072_50720701_15_dialog_content = "Buena pregunta, Arrie, y eso es lo que hizo única a la espada.",
  ui_story_5072_50720701_16_dialog_content = "Si tu espada fue específicamente forjada para ser empuñada solo por ti...",
  ui_story_5072_50720701_17_dialog_content = "Entonces, esta espada fue específicamente creada para que cualquiera la use.",
  ui_story_5072_50720701_18_dialog_content = "Así que incluso aquellos sin habilidades de combate podrían defenderse.",
  ui_story_5072_50720701_19_dialog_content = "Pero obviamente, podría causar un problema mucho más aterrador...",
  ui_story_5072_50720701_20_dialog_content = "En la mano de un debilucho, es protección. Pero en la mano de un bruto...",
  ui_story_5072_50720701_21_dialog_content = "Sí, eso lo convertiría en un arma homicida.",
  ui_story_5072_50720701_22_dialog_content = "Entiendo...",
  ui_story_5072_50720701_23_dialog_content = "Esa es una espada lamentable y explotada.",
  ui_story_5072_50720701_24_dialog_content = "Probablemente su creador estaba demasiado inmerso en sus visiones como para prever algo así...",
  ui_story_5072_50720701_25_dialog_content = "Ya informé la situación y los riesgos a los Lin y a la sede central.",
  ui_story_5072_50720701_26_dialog_content = "Entonces estarían al tanto del Anfitrión de Vilanor y los posibles cerebros detrás de él.",
  ui_story_5072_50720701_27_dialog_content = "Los asaltos nocturnos no deberían volver a ser un suceso regular.",
  ui_story_5072_50720701_28_dialog_content = "Eso explica el cartel de recompensa que vi. Tú les alertaste sobre ello.",
  ui_story_5072_50720701_29_dialog_content = "¡Debo aumentar mi esfuerzo para no quedarme atrás!",
  ui_story_5072_50720701_30_dialog_content = "Vamos, no seas tan tenso.",
  ui_story_5072_50720701_31_dialog_content = "No podría haberlo hecho sin tu esfuerzo.",
  ui_story_5072_50720701_32_dialog_content = "Solo necesitas seguir haciendo lo que has estado haciendo. Visitaremos nuestro próximo objetivo en los próximos días.",
  ui_story_5072_50720701_33_dialog_content = "Pero no golpeemos los arbustos y asustemos a la serpiente.",
  ui_story_5072_50720701_34_dialog_content = "¿Qué serpiente...?",
  ui_story_5072_50720701_35_dialog_content = "¿Serpiente?",
  ui_story_5072_50720701_36_dialog_content = "Oh, eso es una figura retórica, pero conozco un lugar al que debería llevarte ahora.",
  ui_story_5072_50720701_37_dialog_content = "¿Dónde?",
  ui_story_5072_50720701_38_dialog_content = "Un boticario, con todas las hierbas medicinales bajo el sol y un herbolario de primera categoría.",
  ui_story_5072_50720701_39_dialog_content = "Permíteme llevar a mi señora allí y que se cure en el proceso.",
  ui_story_5072_50720701_40_dialog_content = "Eh, mmm...",
  ui_story_5072_50720701_41_dialog_content = "Lo siento, me encontré con un ladrón y no pude evitarlo.",
  ui_story_5072_50720701_42_dialog_content = "No hay nada de qué sentirse culpable. Eso te hace más que un mercenario. Eso te convierte en un héroe.",
  ui_story_5072_50720701_43_dialog_content = "Me halagas. Estoy preocupado de que este disfraz que conseguiste para mí pueda dañarse...",
  ui_story_5072_50720701_44_dialog_content = "No te preocupes por eso. Las cosas se dañan todo el tiempo. Sin mencionar que hay un sastre cerca de la botica.",
  ui_story_5072_50720701_45_dialog_content = "Además, tenemos muchas provisiones en reserva.",
  ui_story_5072_50720701_46_dialog_content = "Eres una socialité de Longzhou, después de todo, y mereces más de un atuendo.",
  ui_story_5072_50720701_47_dialog_content = "Ven, vamos de compras en la calle Chunxi.",
  ui_story_5072_50720701_48_dialog_content = "Bien, entendido.",
  ui_story_5072_50720701_49_dialog_content = "¡Bienvenido! ¿Cómo puedo ayudar... Oh, eres tú.",
  ui_story_5072_50720701_50_dialog_content = "¿Estás tratando de decir que no soy bienvenido?",
  ui_story_5072_50720701_51_dialog_content = "El maestro no está hoy. Puedo darte un descuento regular si quieres lo básico para hacer bebidas herbales. No me lo pongas difícil.",
  ui_story_5072_50720701_52_dialog_content = "Dijiste eso como si me aprovechara de ti cada vez.",
  ui_story_5072_50720701_53_dialog_content = "Bueno, siempre has encontrado la manera de regatear todo bastante.",
  ui_story_5072_50720701_54_dialog_content = "Es mucho más fácil para mí simplemente deshacerme de ti lo antes posible.",
  ui_story_5072_50720701_55_dialog_content = "Está bien, has dejado claro tu punto. No vine por nada especial hoy.",
  ui_story_5072_50720701_56_dialog_content = "Y no soy yo quien necesita atención médica. Es la señora aquí a mi lado.",
  ui_story_5072_50720701_57_dialog_content = "La dama está acostumbrada a lo mejor, ¡así que asegúrate de sacar el stock de calidad!",
  ui_story_5072_50720701_58_dialog_content = "No voy a escatimar en un recién llegado.",
  ui_story_5072_50720701_59_dialog_content = "Arruinar mi propia reputación no es un gran problema, pero arruinar la de mi maestro sí lo es.",
  ui_story_5072_50720701_60_dialog_content = "Oh, y el paciente...",
  ui_story_5072_50720701_61_dialog_content = "¿Qué hay de mí...?",
  ui_story_5072_50720701_62_dialog_content = "Oye, ¿puedo hablar contigo en privado?",
  ui_story_5072_50720701_63_dialog_content = "Está bien. Solo di lo que piensas.",
  ui_story_5072_50720701_64_dialog_content = "Las heridas de esta señora no son normales, sino una condición crónica durante muchos años...",
  ui_story_5072_50720701_65_dialog_content = "Encarnaba un odio intenso.",
  ui_story_5072_50720701_66_dialog_content = "Probablemente sea un milagro que ella siga viva con esa cosa.",
  ui_story_5072_50720701_67_dialog_content = "¿Quién es ella...",
  ui_story_5072_50720701_68_dialog_content = "Es grosero seguir esa línea de preguntas.",
  ui_story_5072_50720701_69_dialog_content = "Bien, entendido eso.",
  ui_story_5072_50720701_70_dialog_content = "Pero no es un problema que la medicina normal pueda resolver, más allá de aliviar algo de dolor en la piel.",
  ui_story_5072_50720701_71_dialog_content = "Lo siento, mujer joven.",
  ui_story_5072_50720701_72_dialog_content = "Está bien. Gracias por el diagnóstico.",
  ui_story_5072_50720701_73_dialog_content = "Estoy acostumbrado a tener este cuerpo, y estoy muy agradecido por los atuendos y la medicina.",
  ui_story_5072_50720701_74_dialog_content = "La cultura de Longzhou realmente es nada menos que asombrosa.",
  ui_story_5072_50720701_75_dialog_content = "¿Pero no eres de Longzhou...?",
  ui_story_5072_50720701_76_dialog_content = "No te preocupes por eso y prepara las hierbas! Por cierto, también necesito una lista.",
  ui_story_5072_50720701_77_dialog_content = "¿No acabas de prometer no regatear ni aprovecharte de mí?",
  ui_story_5072_50720701_78_dialog_content = "Solo estoy haciendo esto porque me trajiste un nuevo paciente... Bien, ¿qué tipo de lista?",
  ui_story_5072_50720701_79_dialog_content = "Nombres de las víctimas apuñaladas recientemente. Cuanto más detalle, mejor.",
  ui_story_5072_50720701_80_dialog_content = "...",
  ui_story_5072_50720701_81_dialog_content = "Bien, pero reunir la lista y las hierbas va a llevar algún tiempo.",
  ui_story_5072_50720701_82_dialog_content = "A cambio, ¿por qué no te encargas de las ratas del agua?",
  ui_story_5072_50720701_83_dialog_content = "¿Ratas? ¿No deberías estar sirviéndonos té en su lugar?",
  ui_story_5072_50720701_84_dialog_content = "¡Absolutamente... NO!",
  ui_story_5072_50720702_1_dialog_content = "Conseguimos la medicina, el nuevo atuendo y, lo más importante, la lista.",
  ui_story_5072_50720702_2_dialog_content = "Todo parece ir bien cuando estás cerca, Arrie.",
  ui_story_5072_50720702_3_dialog_content = "Pero yo no hice nada en absoluto... De hecho, tú hiciste todo por mí.",
  ui_story_5072_50720702_4_dialog_content = "No no, actuaste excelentemente como siempre.",
  ui_story_5072_50720702_5_dialog_content = "¿En serio?",
  ui_story_5072_50720702_6_dialog_content = "De lo contrario, el aprendiz me habría echado de la tienda.",
  ui_story_5072_50720702_7_dialog_content = "Hablaremos de eso más tarde. Ven a ver la lista.",
  ui_story_5072_50720702_8_dialog_content = "Tienes mucha más experiencia con las espadas que yo, así que quiero tu opinión.",
  ui_story_5072_50720702_9_dialog_content = "Bien...",
  ui_story_5072_50720702_10_dialog_content = "Mmm...",
  ui_story_5072_50720702_11_dialog_content = "Es extremadamente detallado. No es de extrañar que sea tu informante de confianza.",
  ui_story_5072_50720702_12_dialog_content = "Ese aprendiz también es sobresaliente.",
  ui_story_5072_50720702_13_dialog_content = "Puede parecer joven, pero es bastante sabio y un gran médico.",
  ui_story_5072_50720702_14_dialog_content = "Habla todo el tiempo sobre salvar vidas y ayudar a los enfermos. Está decidido a curar al mundo entero.",
  ui_story_5072_50720702_15_dialog_content = "¿Curar qué?",
  ui_story_5072_50720702_16_dialog_content = "Curarte, mi señora.",
  ui_story_5072_50720702_17_dialog_content = "No importa, estamos divagando. Solo revisa el resto de la lista.",
  ui_story_5072_50720702_18_dialog_content = "Está bien...",
  ui_story_5072_50720702_19_dialog_content = "De esta lista, veo que varios marineros que trabajaban en el muelle fueron apuñalados recientemente.",
  ui_story_5072_50720702_20_dialog_content = "No podían describir lo que les sucedió más que convulsiones, desmayos o un aura negra alrededor de sus rostros.",
  ui_story_5072_50720702_21_dialog_content = "Eso es muy similar a lo que vi en la casa de ese coleccionista.",
  ui_story_5072_50720702_22_dialog_content = "Es probable que el Anfitrión de Vilanor esté detrás de todo esto. Entonces, ¿quizás esté activo en esa parte de la ciudad?",
  ui_story_5072_50720702_23_dialog_content = "Estamos en la misma página.",
  ui_story_5072_50720702_24_dialog_content = "Los productos de Longzhou suelen ser enviados por agua.",
  ui_story_5072_50720702_25_dialog_content = "Nos conviene preguntar a los marineros que navegan el Río Dorado.",
  ui_story_5072_50720702_26_dialog_content = "Ya que vamos por ese camino, ¿por qué no apuntamos a un pez grande?",
  ui_story_5072_50720702_27_dialog_content = "Seguro. Entonces, ¿cuál es nuestro próximo objetivo?",
  ui_story_5072_50720702_28_dialog_content = "La Galera del Río de Oro preferida por los comerciantes adinerados.",
  ui_story_5072_50720702_29_dialog_content = "¿Debería colarme?",
  ui_story_5072_50720702_30_dialog_content = "No-no. No olvides que ahora eres un socialité de Longzhou.",
  ui_story_5072_50720702_31_dialog_content = "Es natural que contrates a algunos empleados y llegues allí en un yate.",
  ui_story_5072_50720702_32_dialog_content = "¿Es eso necesario?",
  ui_story_5072_50720702_33_dialog_content = "Por supuesto. Si puedes entrar, eso significa que estamos cerca de la fuente del mercado negro.",
  ui_story_5072_50720702_34_dialog_content = "Y para quien trabaja el Anfitrión de Vilanor es o rico o prestigioso.",
  ui_story_5072_50720702_35_dialog_content = "Dado que la galera es un punto de encuentro de alta sociedad, el sigilo funciona tan bien como buscar una aguja en un pajar.",
  ui_story_5072_50720702_36_dialog_content = "Es mejor para nosotros ofrecer pistas o riquezas y atraer a la serpiente.",
  ui_story_5072_50720702_37_dialog_content = "Atrae a la serpiente...",
  ui_story_5072_50720702_38_dialog_content = "¿Algún problema con eso?",
  ui_story_5072_50720702_39_dialog_content = "Tengo la sensación de que te gustan las serpientes.",
  ui_story_5072_50720702_40_dialog_content = "Bueno, eh...",
  ui_story_5072_50720703_1_dialog_content = "...",
  ui_story_5072_50720703_2_dialog_content = "Ejem, ¿está el dueño?",
  ui_story_5072_50720703_3_dialog_content = "Aquí vengo... Oye, ¿en qué puedo ayudarte, jovencita?",
  ui_story_5072_50720703_4_dialog_content = "¿Es este el barco que me llevará a la Galera del Río Dorado?",
  ui_story_5072_50720703_5_dialog_content = "Has venido al lugar correcto. Es el barco más rápido para eso.",
  ui_story_5072_50720703_6_dialog_content = "Sin embargo...",
  ui_story_5072_50720703_7_dialog_content = "¿Hay algún problema?",
  ui_story_5072_50720703_8_dialog_content = "Los patrocinadores adinerados y sus grupos a menudo optan por alquilar un barco para sus eventos.",
  ui_story_5072_50720703_9_dialog_content = "Va a ser una espera para los pasajeros regulares.",
  ui_story_5072_50720703_10_dialog_content = "¡¿Cómo te atreves a insinuar que no puedo permitirme tu servicio?!",
  ui_story_5072_50720703_11_dialog_content = "No puedo creer lo groseras que son las personas en Twin Pavilions Bay...",
  ui_story_5072_50720703_12_dialog_content = "No-no, eso no es lo que quise decir.",
  ui_story_5072_50720703_13_dialog_content = "Estás vestido con elegancia, pero completamente solo.",
  ui_story_5072_50720703_14_dialog_content = "Hay muchos operadores sin escrúpulos en este muelle que solo buscan ganancias.",
  ui_story_5072_50720703_15_dialog_content = "Pero apostamos nuestra reputación en la equidad y la confianza.",
  ui_story_5072_50720703_16_dialog_content = "Además de ofrecerte un precio razonable, puedo encontrar una tripulación confiable y segura.",
  ui_story_5072_50720703_17_dialog_content = "¿Tenemos un trato?",
  ui_story_5072_50720703_18_dialog_content = "Me gusta cómo piensas.",
  ui_story_5072_50720703_19_dialog_content = "No me importa mucho nada excepto la actitud.",
  ui_story_5072_50720703_20_dialog_content = "Haz lo que tengas que hacer.",
  ui_story_5072_50720703_21_dialog_content = "Me pondré manos a la obra de inmediato.",
  ui_story_5072_50720703_22_dialog_content = "¡Tengo un trabajo para ustedes, marineros!",
  ui_story_5072_50720703_23_dialog_content = "¡Sí!",
  ui_story_5072_50720801_1_dialog_content = "¿Le resulta cómoda la cabina, mi señora?",
  ui_story_5072_50720801_2_dialog_content = "Es lo suficientemente adecuado.",
  ui_story_5072_50720801_3_dialog_content = "¡Los remeros darán todo lo que tienen para llevarte allí a tiempo!",
  ui_story_5072_50720801_4_dialog_content = "Si pudieras ofrecer un pequeño incentivo, podríamos ir aún más rápido...",
  ui_story_5072_50720801_5_dialog_content = "Bueno, la velocidad no lo es todo, y no estoy seguro si tu nave está suficientemente construida para eso.",
  ui_story_5072_50720801_6_dialog_content = "Eso no debería ser una preocupación.",
  ui_story_5072_50720801_7_dialog_content = "Nuestra tripulación tiene una docena de años de experiencia. Tu seguridad está asegurada.",
  ui_story_5072_50720801_8_dialog_content = "¿No es una preocupación?",
  ui_story_5072_50720801_9_dialog_content = "¿Crees que no sé que muchos marineros han sido heridos por el Anfitrión de Vilanor últimamente?",
  ui_story_5072_50720801_10_dialog_content = "Supongo que actualmente hay escasez de personas confiables.",
  ui_story_5072_50720801_11_dialog_content = "Vaya, tienes buenas fuentes.",
  ui_story_5072_50720801_12_dialog_content = "Pero lo que no te das cuenta es que la Bahía nunca escasea de marineros.",
  ui_story_5072_50720801_13_dialog_content = "Y el problema del Anfitrión de Vilanor no causó ningún daño en eso.",
  ui_story_5072_50720801_14_dialog_content = "¿Ni un rasguño? Entonces, ¿no te preocupa que él regrese y arruine los negocios en el muelle?",
  ui_story_5072_50720801_15_dialog_content = "No se preocupe, mi señora. Él no se ha mostrado de nuevo desde aquella noche.",
  ui_story_5072_50720801_16_dialog_content = "El verdadero problema detrás de todo eso es, bueno, los peces gordos que descargan cosas en el mercado negro.",
  ui_story_5072_50720801_17_dialog_content = "Muchos de ellos tratan con piratas o criminales.",
  ui_story_5072_50720801_18_dialog_content = "Pueden hacer lo que quieran siempre que el gremio haga la vista gorda, y nos lo ponen difícil a nosotros, los negocios legítimos.",
  ui_story_5072_50720801_19_dialog_content = "El barco más nuevo en el Río Dorado fue comprado por uno de esos peces gordos.",
  ui_story_5072_50720801_20_dialog_content = "Se rumorea que también es dueño de esa elegante galería.",
  ui_story_5072_50720801_21_dialog_content = "Suspiro...",
  ui_story_5072_50720801_22_dialog_content = "¿Sobre qué hay que suspirar?",
  ui_story_5072_50720801_23_dialog_content = "Para mí, su barco es mucho inferior al de los Lin y no es tan bueno.",
  ui_story_5072_50720801_24_dialog_content = "Oh, mi dama. Estos son solo barcos de pasajeros. ¿Cómo podrían rivalizar con los cargueros oceánicos de los Lins?",
  ui_story_5072_50720801_25_dialog_content = "Pero para barcos pequeños como el mío, aún está fuera de nuestro alcance.",
  ui_story_5072_50720801_26_dialog_content = "No podían oponerse a los Lin, pero ciertamente tienen suficiente para molestarnos a los pequeños.",
  ui_story_5072_50720801_27_dialog_content = "¿Cómo están haciendo eso?",
  ui_story_5072_50720801_28_dialog_content = "Dinero de protección, por supuesto; supuestamente para mantener nuestras embarcaciones a salvo de los Eclipsites.",
  ui_story_5072_50720801_29_dialog_content = "Terminamos pagando más y más pero aún no vemos ni un Eclipsite menos.",
  ui_story_5072_50720801_30_dialog_content = "¡Estoy empezando a pensar que están en confabulación!",
  ui_story_5072_50720801_31_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5072_50720801_32_dialog_content = "¿Qué fue eso? ¡No me digas que nos topamos con otro barco a plena luz del día!",
  ui_story_5072_50720801_33_dialog_content = "No te preocupes, mi dama. Es una situación menor, estoy seguro. Permíteme echar un vistazo.",
  ui_story_5072_50720801_34_dialog_content = "Cuidado, Arrie. Vienen los Eclipsites.",
  ui_story_5072_50720801_35_dialog_content = "¿Eclipsites al acecho en Gold River...?",
  ui_story_5072_50720801_36_dialog_content = "Oye, no te acerques más... Ah—",
  ui_story_5072_50720801_37_dialog_content = "<color=#e8d9bb>¡Chapoteo!</color>",
  ui_story_5072_50720801_38_dialog_content = "Necesitamos salvarla.",
  ui_story_5072_50720801_39_dialog_content = "Lo sé. Échame una mano, Espada Mágica.",
  ui_story_5072_50720802_1_dialog_content = "¡Agárrate fuerte!",
  ui_story_5072_50720802_2_dialog_content = "Oh, gracias...",
  ui_story_5072_50720802_3_dialog_content = "Resoplan...",
  ui_story_5072_50720802_4_dialog_content = "¡Gracias por la ayuda! Estos Eclipsites son desagradables. Deberíamos dar la vuelta ahora...",
  ui_story_5072_50720802_5_dialog_content = "Oye, ¿dónde fueron los Eclipsites?",
  ui_story_5072_50720802_6_dialog_content = "Me deshice de todos ellos.",
  ui_story_5072_50720802_7_dialog_content = "¡Dios mío! ¿Hiciste todo eso tú solo?!",
  ui_story_5072_50720802_8_dialog_content = "¡Gracias! Mi barco, mi vida, mi todo se habría ido sin ti.",
  ui_story_5072_50720802_9_dialog_content = "De nada, y no volvamos atrás. Todavía cuento contigo para llevarme a la cocina.",
  ui_story_5072_50720802_10_dialog_content = "Sí, sí, por supuesto. Es solo que...",
  ui_story_5072_50720802_11_dialog_content = "Luchas sorprendentemente bien para ser una chica petite, mi lady.",
  ui_story_5072_50720802_12_dialog_content = "...",
  ui_story_5072_50720802_13_dialog_content = "Y no es un instrumento musical dentro de la caja...",
  ui_story_5072_50720802_14_dialog_content = "Pero una gran espada negra, justo como la que se rumorea que—",
  ui_story_5072_50720802_15_dialog_content = "No, no, quiero decir, ciertamente es una experiencia reveladora.",
  ui_story_5072_50720802_16_dialog_content = "...",
  ui_story_5072_50720802_17_dialog_content = "Pero, eh, hiciste preguntas sobre el Anfitrión de Vilanor tan pronto como subiste a bordo...",
  ui_story_5072_50720802_18_dialog_content = "¿A qué estás llegando?",
  ui_story_5072_50720802_19_dialog_content = "¡Nada!",
  ui_story_5072_50720802_20_dialog_content = "Me salvaste la vida y aquí estoy dudando de ti. Eso no está bien...",
  ui_story_5072_50720802_21_dialog_content = "¿Cómo puedes ser tan brutal, despiadado anfitrión de Vilanor, verdad?",
  ui_story_5072_50720802_22_dialog_content = "Por supuesto que no.",
  ui_story_5072_50720802_23_dialog_content = "¡Esta espada... es una reliquia familiar! La llevaré a la galería para que la tasen.",
  ui_story_5072_50720802_24_dialog_content = "No debería mostrarlo, pero la situación era desesperada...",
  ui_story_5072_50720802_25_dialog_content = "Se le pagará en su totalidad por su servicio, y su seguridad está asegurada durante el resto de este viaje.",
  ui_story_5072_50720802_26_dialog_content = "¡Solo concéntrate en llevarme a mi destino!",
  ui_story_5072_50720802_27_dialog_content = "¡S-Claro! Por favor, tome asiento en su cabina y estaremos allí en breve!",
  ui_story_5072_50720901_1_dialog_content = "¡Aquí estamos! La cocina, mi señora.",
  ui_story_5072_50720901_2_dialog_content = "Simplemente sube y alguien estará allí para acogerte.",
  ui_story_5072_50720901_3_dialog_content = "Creo que eso fue innecesario, ya que debes conocer los protocolos mucho mejor que yo.",
  ui_story_5072_50720901_4_dialog_content = "Está bien. Gracias por las indicaciones.",
  ui_story_5072_50720901_5_dialog_content = "Así que este es el Galería del Río de Oro... Definitivamente un lugar muy animado.",
  ui_story_5072_50720901_6_dialog_content = "¿O quizás más precisamente, una mezcla de cosas? Siento muchas cosas diferentes.",
  ui_story_5072_50720901_7_dialog_content = "Hasta ahora, no puedo confirmar si el Anfitrión de Vilanor tiene algo que ver con aquí.",
  ui_story_5072_50720901_8_dialog_content = "Entendido. Gracias, seré cuidadoso.",
  ui_story_5072_50720901_9_dialog_content = "Y también hice la tarea antes de venir.",
  ui_story_5072_50720901_10_dialog_content = "Lo que dijiste sobre Vilanor controlando las sombras y la energía, Arrie...",
  ui_story_5072_50720901_11_dialog_content = "Supongo que podría dejar rastros en objetos específicos, como los utensilios que tocó.",
  ui_story_5072_50720901_12_dialog_content = "Las antigüedades animadas emiten un aura negra...",
  ui_story_5072_50720901_13_dialog_content = "Podrían haber sido encantados por el Vilanor.",
  ui_story_5072_50720901_14_dialog_content = "¿Es una especie de firma?",
  ui_story_5072_50720901_15_dialog_content = "En ese caso, la reunión en la Galera del Río Dorado es mucho más de lo que parece a simple vista.",
  ui_story_5072_50720901_16_dialog_content = "¿Qué se encuentra a la vista...?",
  ui_story_5072_50720901_17_dialog_content = "Sí. Si el Anfitrión de Vilanor es el ejecutor exclusivo para la mente maestra...",
  ui_story_5072_50720901_18_dialog_content = "Es muy posible que intente ganarnos en la venta de las reliquias de Longzhou.",
  ui_story_5072_50720901_19_dialog_content = "Elimina las pistas para que nadie pueda seguir.",
  ui_story_5072_50720901_20_dialog_content = "Después de todo, ha estado trabajando en Twin Pavilions Bay durante mucho tiempo.",
  ui_story_5072_50720901_21_dialog_content = "Ningún forastero puede comprender cuán profundo es, sin importar qué apoyo obtuvieron de los Lin y la sede.",
  ui_story_5072_50720901_22_dialog_content = "Después de que pase y sea olvidado, puede reaparecer en el mercado negro de nuevo.",
  ui_story_5072_50720901_23_dialog_content = "Entonces, ¿crees que el Anfitrión de Vilanor estará en la cocina?!",
  ui_story_5072_50720901_24_dialog_content = "Sí, y probablemente también quien vendió la espada a Twin Pavilions Bay. Necesitaré confirmar eso...",
  ui_story_5072_50720901_25_dialog_content = "Gracias, damas y caballeros, por tomar tiempo de sus ocupadas agendas para venir a bordo de mi Galera Gold River.",
  ui_story_5072_50720901_26_dialog_content = "Tenemos coleccionables nuevos para que los valores y compres. Siéntete libre de decir un precio.",
  ui_story_5072_50720901_27_dialog_content = "Pero tengo una solicitud personal que me gustaría que todos ustedes ayudaran...",
  ui_story_5072_50720901_28_dialog_content = "Recientemente perdí una reliquia preciosa. Es una espada arcana del extranjero...",
  ui_story_5072_50720901_29_dialog_content = "...!!!",
  ui_story_5072_50720901_30_dialog_content = "La espada es increíblemente intrincada, por la cual gasté una fortuna para adquirirla.",
  ui_story_5072_50720901_31_dialog_content = "Desafortunadamente, nunca llegué a blandirlo antes de perderlo. Por lo tanto...",
  ui_story_5072_50720901_32_dialog_content = "Tuve que adelantar esta reunión con la esperanza de solicitar pistas de usted.",
  ui_story_5072_50720901_33_dialog_content = "...",
  ui_story_5072_50720901_34_dialog_content = "<size=30>¿Espada Arcana? ¿No es esa la forma original de la Vilanor que describió la señorita Armilla?</size>",
  ui_story_5072_50720901_35_dialog_content = "<size=30>¡Tengo que sondear un poco!</size>",
  ui_story_5072_50720901_36_dialog_content = "Señor, ¿ha oído hablar del reciente apuñalamiento por parte del Anfitrión de Vilanor en Twin Pavilions Bay?",
  ui_story_5072_50720901_37_dialog_content = "¿Te refieres al incidente del coleccionista de Lumopolis? He oído una cosa o dos.",
  ui_story_5072_50720901_38_dialog_content = "Pero, ¿qué tiene que ver él con mi espada arcana?",
  ui_story_5072_50720901_39_dialog_content = "Perdiste la espada solo para que aparezca un espadachín despiadado en Twin Pavilions Bay.",
  ui_story_5072_50720901_40_dialog_content = "Si él estaba usando tu espada, ¿no serías también algo responsable?",
  ui_story_5072_50720901_41_dialog_content = "Mi dama, mi espada es simplemente una pieza de colección.",
  ui_story_5072_50720901_42_dialog_content = "Lo compré a un costo elevado solo por curiosidad. Soy la víctima en la pérdida.",
  ui_story_5072_50720901_43_dialog_content = "Y que el Anfitrión de Vilanor solo lastima a las personas porque él mismo es malvado.",
  ui_story_5072_50720901_44_dialog_content = "No haría diferencia si él usara una espada arcana, una espada ropera o una espada ancha, ¿entiendes?",
  ui_story_5072_50720901_45_dialog_content = "¿Es eso cierto...?",
  ui_story_5072_50720901_46_dialog_content = "Aquí viene.",
  ui_story_5072_50720901_47_dialog_content = "Tan insoportable el dolor y el desprecio... ¿Qué habrá sufrido...?",
  ui_story_5072_50720901_48_dialog_content = "De la antigua fuerza interior nació la espada maldita...",
  ui_story_5072_50720901_49_dialog_content = "El mal probablemente está más allá de lo que podrías imaginar.",
  ui_story_5072_50720901_50_dialog_content = "¿O tienes la intención de rastrear a todos los que conocen el paradero del Anfitrión de Vilanor...",
  ui_story_5072_50720901_51_dialog_content = "¿Y eliminarlos a todos para cubrir tus propias huellas?",
  ui_story_5072_50720901_52_dialog_content = "¿Por qué me estás difamando? ¿Quién eres? ¡No recuerdo haberte invitado!",
  ui_story_5072_50720901_53_dialog_content = "¡Guardias, vengan a expulsar a esta mujer mentirosa del lugar!",
  ui_story_5072_50720901_54_dialog_content = "¿Dónde están los guardias?",
  ui_story_5072_50720901_55_dialog_content = "¡Algo esta mal!",
  ui_story_5072_50720901_56_dialog_content = "...",
  ui_story_5072_50721001_1_dialog_content = "rugir—",
  ui_story_5072_50721001_2_dialog_content = "¿Quién eres tú? ¡¿Cómo te atreves a irrumpir?!",
  ui_story_5072_50721001_3_dialog_content = "¡Espera, no es esa mi espada arcana la que estás sosteniendo?!",
  ui_story_5072_50721001_4_dialog_content = "No viniste aquí solo para devolvérmelo, ¿verdad?",
  ui_story_5072_50721001_5_dialog_content = "¡Es el Anfitrión de Vilanor! ¡Está aquí! Sabía que el dueño de la galera estaba detrás de esto...",
  ui_story_5072_50721001_6_dialog_content = "No, su interés en la espada parecía lo suficientemente inocente y desconocía la amenaza que representaba el Anfitrión de Vilanor.",
  ui_story_5072_50721001_7_dialog_content = "Pero, ¿qué hace el Anfitrión de Vilanor aquí?",
  ui_story_5072_50721001_8_dialog_content = "Venganza...",
  ui_story_5072_50721001_9_dialog_content = "¿Venganza?",
  ui_story_5072_50721001_10_dialog_content = "¡Para! ¿Qué es lo que quieres? ¡Solo elige cualquier cosa aquí y será tuyo!",
  ui_story_5072_50721001_11_dialog_content = "Yo... quiero... a ti...",
  ui_story_5072_50721001_12_dialog_content = "¿Qué...?",
  ui_story_5072_50721001_13_dialog_content = "¡Cuidado!",
  ui_story_5072_50721001_14_dialog_content = "¡Quiero que mueras!",
  ui_story_5072_50721001_15_dialog_content = "¡Swoosh—!",
  ui_story_5072_50721001_16_dialog_content = "¡Uh!",
  ui_story_5072_50721001_17_dialog_content = "¡El anfitrión de Vilanor! ¡Es el anfitrión de Vilanor!",
  ui_story_5072_50721001_18_dialog_content = "Qué debería hacer ahora...?",
  ui_story_5072_50721001_19_dialog_content = "¡Estoy listo, Arrie!",
  ui_story_5072_50721001_20_dialog_content = "Las sombras oscuras no pueden interferir aquí.",
  ui_story_5072_50721001_21_dialog_content = "Podemos sorprenderlo y ganar de manera decisiva.",
  ui_story_5072_50721001_22_dialog_content = "Entendido. Cuento contigo, Espada mágica...",
  ui_story_5072_50721001_23_dialog_content = "¡Pato!",
  ui_story_5072_50721001_24_dialog_content = "¡Swoosh—!",
  ui_story_5072_50721001_25_dialog_content = "¿Qué... Ugh!",
  ui_story_5072_50721001_26_dialog_content = "¡Ruido!",
  ui_story_5072_50721001_27_dialog_content = "¿Qué pasó... Se acabó?",
  ui_story_5072_50721001_28_dialog_content = "¿El Anfitrión de Vilanor que tiene una recompensa por su cabeza en todas partes cayó así de fácil?",
  ui_story_5072_50721001_29_dialog_content = "No puede ser tan simple. ¡Probablemente esto esté montado para aumentar el precio de la espada!",
  ui_story_5072_50721001_30_dialog_content = "Es cierto, no creo que una espada pueda ser malvada, o hacer malvado a quien la empuña.",
  ui_story_5072_50721001_31_dialog_content = "Es solo una espada arcana extranjera. Mira, no tiene nada de malvado...",
  ui_story_5072_50721001_32_dialog_content = "¡No, bajalo!",
  ui_story_5072_50721001_33_dialog_content = "¡Ugh! ¡Venganza... Venganza!",
  ui_story_5072_50721001_34_dialog_content = "Está poseído.",
  ui_story_5072_50721001_35_dialog_content = "¡Maldita sea!",
  ui_story_5072_50721001_36_dialog_content = "¡Es ciertamente la espada la que es el problema! ¡Tiene una maldición!",
  ui_story_5072_50721001_37_dialog_content = "¡Quien lo posea se convierte en el Anfitrión de Vilanor!",
  ui_story_5072_50721001_38_dialog_content = "Y se está volviendo más fuerte cuanto más personas posee.",
  ui_story_5072_50721001_39_dialog_content = "¿Qué estás mirando... espadachín!",
  ui_story_5072_50721001_40_dialog_content = "¡Cuidado, hemos captado su atención!",
  ui_story_5072_50721001_41_dialog_content = "¡Sonido metálico—!",
  ui_story_5072_50721001_42_dialog_content = "Oh...",
  ui_story_5072_50721001_43_dialog_content = "Está golpeando más fuerte ahora.",
  ui_story_5072_50721001_44_dialog_content = "Es como si yo y mi espada de alguna manera lo hubiéramos emocionado...",
  ui_story_5072_50721001_45_dialog_content = "¡Sonido metálico—!",
  ui_story_5072_50721001_46_dialog_content = "Como espadachín... eres patético.",
  ui_story_5072_50721001_47_dialog_content = "Así que como yo, tú no eres un espadachín...",
  ui_story_5072_50721001_48_dialog_content = "¡Ignóralo y probemos de nuevo!",
  ui_story_5072_50721001_49_dialog_content = "¡Ugh...!",
  ui_story_5072_50721001_50_dialog_content = "¡Swoosh— ¡Clang—!",
  ui_story_5072_50721001_51_dialog_content = "No puedes lastimarme de esta manera.",
  ui_story_5072_50721001_52_dialog_content = "Puede que tengas tu propia conciencia, pero en realidad también eres solo un intermediario...",
  ui_story_5072_50721001_53_dialog_content = "Uno controlado por una espada, incapaz de liberar su verdadero poder.",
  ui_story_5072_50721001_54_dialog_content = "La razón por la que no puedo vencerte ahora es porque...",
  ui_story_5072_50721001_55_dialog_content = "(Está demasiado lleno aquí como para blandir mi espada libremente...)",
  ui_story_5072_50721001_56_dialog_content = "(Pero tengo que ocultar ese hecho o será peor cuando tome un rehén...)",
  ui_story_5072_50721001_57_dialog_content = "(¿Qué hacer...)",
  ui_story_5072_50721001_58_dialog_content = "¿Sabes nadar, Arrie?",
  ui_story_5072_50721001_59_dialog_content = "¿Qué? Sí, un poco... ¿Tienes una idea, Espada Mágica?",
  ui_story_5072_50721001_60_dialog_content = "Ya tracé la ruta. Llevas al Anfitrión de Vilanor en el bote contigo.",
  ui_story_5072_50721001_61_dialog_content = "¡Entonces golpéalo hasta que caiga al agua!",
  ui_story_5072_50721001_62_dialog_content = "Pero si no eres un nadador fuerte, este es un plan muy arriesgado...",
  ui_story_5072_50721001_63_dialog_content = "Gracias, pero aún voy a intentarlo, ya que esa es la mejor opción que tenemos.",
  ui_story_5072_50721001_64_dialog_content = "¡Te mostraré el verdadero poder de mi Espada Mágica!",
  ui_story_5072_50721001_65_dialog_content = "Ven, sustituto... ¡No eres más que una piedrecita en mi camino de venganza!",
  ui_story_5072_50721002_1_dialog_content = "¡Golpe de espina!",
  ui_story_5072_50721002_2_dialog_content = "¡Urgh...!",
  ui_story_5072_50721002_3_dialog_content = "Qué inesperado.",
  ui_story_5072_50721002_4_dialog_content = "¿Es porque aún no estoy completamente aclimatado a este nuevo cuerpo?",
  ui_story_5072_50721002_5_dialog_content = "Ríndete.",
  ui_story_5072_50721002_6_dialog_content = "¡O mi próximo golpe te enviará al Río Dorado!",
  ui_story_5072_50721002_7_dialog_content = "No poseerás a nadie una vez que hayas tocado fondo.",
  ui_story_5072_50721002_8_dialog_content = "<color=#e8d9bb>¡Clang—!</color>",
  ui_story_5072_50721002_9_dialog_content = "¡Ay! Ugh...",
  ui_story_5072_50721002_10_dialog_content = "¿No vas a rendirte?",
  ui_story_5072_50721002_11_dialog_content = "(Me estoy... cansando...)",
  ui_story_5072_50721002_12_dialog_content = "¿Qué pasa? ¿Dónde está el golpe final que prometiste?",
  ui_story_5072_50721002_13_dialog_content = "¿Puedes aguantar, Arrie?",
  ui_story_5072_50721002_14_dialog_content = "¡Te cubriré, así que ve a por él!",
  ui_story_5072_50721002_15_dialog_content = "Ah...!",
  ui_story_5072_50721002_16_dialog_content = "(Cuanto más se prolonga esta lucha, más aterrador se vuelve el poder de Vilanor...)",
  ui_story_5072_50721002_17_dialog_content = "(No podría haberlo soportado sin la ayuda activa de la Espada Mágica...)",
  ui_story_5072_50721002_18_dialog_content = "(Esta no es una batalla entre el Anfitrión de Vilanor y yo, sino entre las dos espadas.)",
  ui_story_5072_50721002_19_dialog_content = "No, no puedo ser una carga para la Espada Mágica.",
  ui_story_5072_50721002_20_dialog_content = "¿Estás bien, Arrie?",
  ui_story_5072_50721002_21_dialog_content = "Mira, ¿no es ese el anfitrión de Vilanor?",
  ui_story_5072_50721002_22_dialog_content = "¡¿Qué?!",
  ui_story_5072_50721002_23_dialog_content = "¿Se ha acercado el bote a la costa?",
  ui_story_5072_50721002_24_dialog_content = "El número de espectadores también está creciendo. Esto no es bueno...",
  ui_story_5072_50721002_25_dialog_content = "¡No, hay dos espadachines peleando!",
  ui_story_5072_50721002_26_dialog_content = "El que está en la sombra es el Anfitrión de Vilanor, el otro es...",
  ui_story_5072_50721002_27_dialog_content = "¡La famosa mercenaria de Umbraton con espinas por todo su cuerpo, la Espada Mágica Arrie!",
  ui_story_5072_50721002_28_dialog_content = "Oh no, mi atuendo... Mi tapadera está descubierta.",
  ui_story_5072_50721002_29_dialog_content = "Sí, el barco atracará pronto, ¡dándome muchos cuerpos nuevos para poseer!",
  ui_story_5072_50721002_30_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_5072_50721002_31_dialog_content = "Gracias por perdonarme...",
  ui_story_5072_50721002_32_dialog_content = "Espera... Estoy agotado...",
  ui_story_5072_50721002_33_dialog_content = "El Anfitrión de Vilanor se escapó de nuevo... Lo siento mucho...",
  ui_story_5072_50721101_1_dialog_content = "...",
  ui_story_5072_50721101_2_dialog_content = "...",
  ui_story_5072_50721101_3_dialog_content = "Nadie debería verme por aquí.",
  ui_story_5072_50721101_4_dialog_content = "Uf, al menos no tengo que pelear por un tiempo...",
  ui_story_5072_50721101_5_dialog_content = "Vaya, de repente la Espada Mágica se siente tan pesada.",
  ui_story_5072_50721101_6_dialog_content = "¿Qué estás haciendo aquí, Arrie? Te he estado buscando.",
  ui_story_5072_50721101_7_dialog_content = "Oh hola...",
  ui_story_5072_50721101_8_dialog_content = "Perdóname por no acercarme a ti.",
  ui_story_5072_50721101_9_dialog_content = "Bueno, tengo buenas noticias para compartir.",
  ui_story_5072_50721101_10_dialog_content = "El cuartel general ha accedido a ayudarnos a traer al Anfitrión de Vilanor y guardar la espada.",
  ui_story_5072_50721101_11_dialog_content = "Así que tenemos un nuevo objetivo y nuestro objetivo principal ahora es...",
  ui_story_5072_50721101_12_dialog_content = "Um, lo siento...",
  ui_story_5072_50721101_13_dialog_content = "¿Disculpa? ¿Qué pasa, Arrie?",
  ui_story_5072_50721101_14_dialog_content = "No creo que pueda continuar con el trabajo.",
  ui_story_5072_50721101_15_dialog_content = "...",
  ui_story_5072_50721101_16_dialog_content = "Debería ser yo quien se disculpe por seguir divagando por mi cuenta.",
  ui_story_5072_50721101_17_dialog_content = "Escuché a la gente hablar sobre dos espadachines luchando en el río. Viendo cómo te ves ahora...",
  ui_story_5072_50721101_18_dialog_content = "¿Algo salió mal cuando luchaste contra el Anfitrión de Vilanor?",
  ui_story_5072_50721101_19_dialog_content = "¡No me digas que algunos de esos marineros tontos te confundieron con el Anfitrión de Vilanor?!",
  ui_story_5072_50721101_20_dialog_content = "Estoy bien incluso si ese es el caso y me miran de reojo. Estoy acostumbrado a eso.",
  ui_story_5072_50721101_21_dialog_content = "Quiero renunciar porque ahora lo entiendo completamente...",
  ui_story_5072_50721101_22_dialog_content = "No puedo vencer al Anfitrión de Vilanor.",
  ui_story_5072_50721101_23_dialog_content = "Como representante, simplemente no puedo vencerlo.",
  ui_story_5072_50721101_24_dialog_content = "¿Apoderado? Ese es un derecho reservado solo para artesanos. No pelees conmigo por eso, Arrie.",
  ui_story_5072_50721101_25_dialog_content = "¿El Anfitrión de Vilanor te metió ideas locas en la cabeza? ¡No lo escuches!",
  ui_story_5072_50721101_26_dialog_content = "No, él tenía razón...",
  ui_story_5072_50721101_27_dialog_content = "Como él, no soy un espadachín sino un representante, por lo que no puedo liberar todo el poder de mi espada.",
  ui_story_5072_50721101_28_dialog_content = "Mientras el Anfitrión de Vilanor tiene acceso completo a su espada, estoy reteniendo la Espada Mágica.",
  ui_story_5072_50721101_29_dialog_content = "Eso es una tontería, Arrie.",
  ui_story_5072_50721101_30_dialog_content = "La tuya es la polar opuesta a esa espada siniestra y vengativa. Te protege.",
  ui_story_5072_50721101_31_dialog_content = "Tu espada estaría triste de escucharte decir eso.",
  ui_story_5072_50721101_32_dialog_content = "No, mi intención no es degradar la Espada Mágica.",
  ui_story_5072_50721101_33_dialog_content = "Cuidó mucho de mí y nunca me llamó un sustituto.",
  ui_story_5072_50721101_34_dialog_content = "Pero siempre he sido yo el dependiente.",
  ui_story_5072_50721101_35_dialog_content = "La espada puede estar sin mí, pero yo no puedo estar sin ella.",
  ui_story_5072_50721101_36_dialog_content = "Es un testimonio del poder de la Espada Mágica que incluso sobreviví para ser un mercenario.",
  ui_story_5072_50721101_37_dialog_content = "Quita eso y solo soy una chica aburrida y débil que no es buena en nada.",
  ui_story_5072_50721101_38_dialog_content = "Vamos, Arrie. Eso no es lo que eres para mí. ¡Eres un mercenario confiable y poderoso por derecho propio!",
  ui_story_5072_50721101_39_dialog_content = "Pero si no tengo la espada, no tendré ningún valor para ti.",
  ui_story_5072_50721101_40_dialog_content = "Al igual que ahora, nadie me verá como una socialité después de romper el atuendo que me diste.",
  ui_story_5072_50721101_41_dialog_content = "Solo soy Arrie, una mercenaria de Umbraton con espinas por todo su cuerpo.",
  ui_story_5072_50721101_42_dialog_content = "Quizás con un portador más grande, derrotará fácilmente al Vilanor.",
  ui_story_5072_50721101_43_dialog_content = "Nadie poseído por el Vilanor es más duro que tú, Arrie.",
  ui_story_5072_50721101_44_dialog_content = "Puede cambiar de portador a voluntad, por lo que tiene una ventaja decisiva en resistencia.",
  ui_story_5072_50721101_45_dialog_content = "Pero no puedo vencerlo. Incluso destrocé el disfraz vital para la misión. Esos son hechos.",
  ui_story_5072_50721101_46_dialog_content = "Quizás deberías contratar a un mercenario mejor para terminar el trabajo.",
  ui_story_5072_50721101_47_dialog_content = "Arrie...",
  ui_story_5072_50721101_48_dialog_content = "...",
  ui_story_5072_50721101_49_dialog_content = "¿A dónde vas, Arrie?",
  ui_story_5072_50721101_50_dialog_content = "No lo sé...",
  ui_story_5072_50721101_51_dialog_content = "¿Vas a renunciar al trabajo? ¿Y también por ti mismo?",
  ui_story_5072_50721101_52_dialog_content = "Simplemente no puedo hacerlo...",
  ui_story_5072_50721101_53_dialog_content = "...",
  ui_story_5072_50721101_54_dialog_content = "Te dejaré la decisión final a ti...",
  ui_story_5072_50721101_55_dialog_content = "Pero antes de que renuncies, ¿te importaría si te cuento una historia?",
  ui_story_5072_50721101_56_dialog_content = "¿Historia?",
  ui_story_5072_50721101_57_dialog_content = "Sí, uno que acabo de escuchar... no, acabo de recordar, sobre un héroe maldito por los Eclipsites.",
  ui_story_5072_50721101_58_dialog_content = "Un héroe antiguo fue maldecido con una enfermedad eterna en su batalla contra los Eclipsites.",
  ui_story_5072_50721101_59_dialog_content = "No solo eso, cualquier descendiente suyo que sea hábil en la caza de Eclipsites también morirá joven debido a la maldición.",
  ui_story_5072_50721101_60_dialog_content = "Cualquier persona normal abandonaría tal destino heroico por miedo.",
  ui_story_5072_50721101_61_dialog_content = "Y recuerda a su familia que se aleje de la formación o cualquier guerra contra los Eclipsites.",
  ui_story_5072_50721101_62_dialog_content = "Pero el héroe eligió usar su cuerpo maldito como el componente base.",
  ui_story_5072_50721101_63_dialog_content = "Y forja una espada bajo la bendición de la luna.",
  ui_story_5072_50721101_64_dialog_content = "Desde entonces, la espada ha protegido a sus descendientes hábiles en la lucha y contra la maldición de los Eclipsites.",
  ui_story_5072_50721101_65_dialog_content = "Todos ellos lucharon valientemente...",
  ui_story_5072_50721102_1_dialog_content = "Eso es todo para la historia.",
  ui_story_5072_50721102_2_dialog_content = "Pero el choque entre los herederos del héroe y los Eclipsites nunca terminará.",
  ui_story_5072_50721102_3_dialog_content = "Cuanto mayor es el guerrero, mayor es la protección que debe proporcionar la espada. Ese es el propósito de la espada.",
  ui_story_5072_50721102_4_dialog_content = "Para mí, eres todo menos insignificante, Arrie. Yo... la Espada Mágica te protegerá...",
  ui_story_5072_50721102_5_dialog_content = "Porque reconozco lo genial que eres.",
  ui_story_5072_50721102_6_dialog_content = "Estoy muy agradecido por eso y siempre lo he estado.",
  ui_story_5072_50721102_7_dialog_content = "¿Pero soy digno de ello?",
  ui_story_5072_50721102_8_dialog_content = "Por supuesto que lo eres. Sé que solo soy una espada.",
  ui_story_5072_50721102_9_dialog_content = "A pesar de una historia antigua y de desarrollar una conciencia, eso es básicamente lo que soy.",
  ui_story_5072_50721102_10_dialog_content = "Decidiste mi destino y a quién golpeé. Aprendiste a controlar mi poder.",
  ui_story_5072_50721102_11_dialog_content = "Tu espíritu nunca decayó a causa de los efectos secundarios que tuve sobre ti.",
  ui_story_5072_50721102_12_dialog_content = "Todo lo contrario, fuiste tú quien me ha estado influenciando, señalando las espinas en la dirección correcta.",
  ui_story_5072_50721102_13_dialog_content = "Eso es totalmente diferente a Vilanor siempre aprovechándose de los demás.",
  ui_story_5072_50721102_14_dialog_content = "Bueno, como portadores, todos estamos protegidos por el gran poder de nuestras respectivas espadas...",
  ui_story_5072_50721102_15_dialog_content = "Te equivocas, Arrie.",
  ui_story_5072_50721102_16_dialog_content = "¿Realmente crees que el Vilanor estaba protegiendo a su portador?",
  ui_story_5072_50721102_17_dialog_content = "¿Ah?",
  ui_story_5072_50721102_18_dialog_content = "Parecía proteger al portador solo porque no quería perder. No le importaba quién lo sostenía.",
  ui_story_5072_50721102_19_dialog_content = "Esa es la naturaleza de Vilanor. Aceptarán a cualquiera.",
  ui_story_5072_50721102_20_dialog_content = "¡Pero tú, Arrie, eres el único y verdadero maestro de mí y de la Espada Mágica!",
  ui_story_5072_50721102_21_dialog_content = "...",
  ui_story_5072_50721102_22_dialog_content = "Soy el maestro de la Espada Mágica...",
  ui_story_5072_50721102_23_dialog_content = "Espera, ¿eso significa que la historia que acabas de contar es el origen de mi espada?!",
  ui_story_5072_50721102_24_dialog_content = "Lo has descubierto... Como te dije antes, solo sé sobre esta espada en particular.",
  ui_story_5072_50721102_25_dialog_content = "Esta espada es más que antigua, así que solo pude reconstruir su memoria a través de fragmentos.",
  ui_story_5072_50721102_26_dialog_content = "Los detalles pueden no ser necesariamente correctos, así que no me culpes.",
  ui_story_5072_50721102_27_dialog_content = "No lo estoy.",
  ui_story_5072_50721102_28_dialog_content = "Esto es lo más que he aprendido sobre la maldición.",
  ui_story_5072_50721102_29_dialog_content = "Gracias.",
  ui_story_5072_50721102_30_dialog_content = "Creo que sé lo que debo hacer.",
  ui_story_5072_50721102_31_dialog_content = "¡Voy a ver a la señorita Armilla y terminar el trabajo!",
  ui_story_5072_50721102_32_dialog_content = "Señorita Armilla...",
  ui_story_5072_50721102_33_dialog_content = "¿Arrie? Ven a sentarte conmigo. Camarero, dame dos cestas más de bollos de sopa con extra de chili.",
  ui_story_5072_50721102_34_dialog_content = "¡Ahora mismo!",
  ui_story_5072_50721102_35_dialog_content = "Uh, ¿vas a encontrarte con un informante aquí?",
  ui_story_5072_50721102_36_dialog_content = "No. El plato y los utensilios son para ti.",
  ui_story_5072_50721102_37_dialog_content = "¿Qué?",
  ui_story_5072_50721102_38_dialog_content = "Solo estabas agotado en ese momento, después de todo. Estaba seguro de que esa Espada Mágica tuya te despejaría la cabeza.",
  ui_story_5072_50721102_39_dialog_content = "¿Sabes acerca de mi espada mágica?",
  ui_story_5072_50721102_40_dialog_content = "No realmente, pero sé cómo ustedes dos pelean.",
  ui_story_5072_50721102_41_dialog_content = "La química que tienes no es algo que el Anfitrión de Vilanor pueda tocar.",
  ui_story_5072_50721102_42_dialog_content = "Lo siento por no haber pensado bien en lo que dijiste antes.",
  ui_story_5072_50721102_43_dialog_content = "No soy solo yo, sin embargo.",
  ui_story_5072_50721102_44_dialog_content = "Todas las personas inocentes en la galería a las que salvaste te agradecen mucho.",
  ui_story_5072_50721102_45_dialog_content = "Todos están esperando con ansias que la heroína acabe con ese malvado Anfitrión de Vilanor con su espada mágica.",
  ui_story_5072_50721102_46_dialog_content = "Bueno, si no es demasiado tarde, ¿puedo terminar el trabajo todavía?",
  ui_story_5072_50721102_47_dialog_content = "¿No he estado diciendo desde el principio que el trabajo es solo tuyo?",
  ui_story_5072_50721102_48_dialog_content = "Comamos mientras la comida está caliente... De todos modos, ¿alguna idea de cómo vencer al Anfitrión de Vilanor?",
  ui_story_5072_50721102_49_dialog_content = "En realidad, tuve la oportunidad de derrotar a Vilanor con la ayuda de la Espada Mágica.",
  ui_story_5072_50721102_50_dialog_content = "¿Oh?",
  ui_story_5072_50721102_51_dialog_content = "Estábamos en un bote y pensé que si podía tirarlo al agua, no podría poseer a nadie de nuevo.",
  ui_story_5072_50721102_52_dialog_content = "Pero estaba demasiado cansado y tímido en ese momento, así que no pude dar el golpe final.",
  ui_story_5072_50721102_53_dialog_content = "Si no hay nadie más cerca y, en lugar de enfrentarme directamente al Anfitrión de Vilanor, lo desarmo de la espada...",
  ui_story_5072_50721102_54_dialog_content = "Quizás esa sea la forma de someterlo.",
  ui_story_5072_50721102_55_dialog_content = "Esa es la Espada Mágica Arrie que conozco. Solo tú podrías idear ese plan.",
  ui_story_5072_50721102_56_dialog_content = "Pero probablemente Vilanor ya esté anticipando eso, por lo que puede que no funcione...",
  ui_story_5072_50721102_57_dialog_content = "Está bien. Encontraremos otra manera de lograr ese fin.",
  ui_story_5072_50721102_58_dialog_content = "Después de todo, acaba de cobrar conciencia hace poco tiempo.",
  ui_story_5072_50721102_59_dialog_content = "Todavía tiene mucho que aprender en cuanto a trucos y estrategias.",
  ui_story_5072_50721102_60_dialog_content = "Toma un descanso por ahora, Arrie, y cambiate mientras preparo las cosas.",
  ui_story_5072_50721102_61_dialog_content = "¡Lancemos el golpe final a Vilanor esta noche!",
  ui_story_5072_50721201_1_dialog_content = "Lo siento, Arrie, por llegar aquí tarde.",
  ui_story_5072_50721201_2_dialog_content = "Me llevó más tiempo del que pensaba informar a los chicos enviados por la sede sobre mi plan.",
  ui_story_5072_50721201_3_dialog_content = "Pero todo está listo para ir ahora. ¿Estás listo para el enfrentamiento final con el Anfitrión de Vilanor?",
  ui_story_5072_50721201_4_dialog_content = "Estoy listo. Pero, ¿a dónde voy?",
  ui_story_5072_50721201_5_dialog_content = "La muralla.",
  ui_story_5072_50721201_6_dialog_content = "La muralla... Lo entiendo.",
  ui_story_5072_50721201_7_dialog_content = "Derríbalo del parapeto y no habrá nadie alrededor para que pueda poseer.",
  ui_story_5072_50721201_8_dialog_content = "Ese es el plan. Pero no será fácil atraer al espadachín hasta allí.",
  ui_story_5072_50721201_9_dialog_content = "Avistamos al Anfitrión de Vilanor, señorita Armilla.",
  ui_story_5072_50721201_10_dialog_content = "Está bien. Debemos darnos prisa.",
  ui_story_5072_50721201_11_dialog_content = "...",
  ui_story_5072_50721201_12_dialog_content = "Ah, veo a mucha gente.",
  ui_story_5072_50721201_13_dialog_content = "¿Pero crees que esto es todo lo que se necesita para someterme?",
  ui_story_5072_50721201_14_dialog_content = "¡Estás peleando conmigo!",
  ui_story_5072_50721201_15_dialog_content = "Oye, ¿no eres el representante?",
  ui_story_5072_50721201_16_dialog_content = "¿Toqué un punto sensible? ¿Es por eso que sigues acosándome?",
  ui_story_5072_50721201_17_dialog_content = "¡Entonces demostraré cuán inferior eres a mí!",
  ui_story_5072_50721201_18_dialog_content = "<color=#e8d9bb>¡Sonido metálico! ¡Sonido metálico!</color>",
  ui_story_5072_50721201_19_dialog_content = "Sigues siendo débil como siempre. No puedes defender mis golpes sin tu espada mágica.",
  ui_story_5072_50721201_20_dialog_content = "Estoy en una terrible ventaja...",
  ui_story_5072_50721201_21_dialog_content = "Sigue retrocediendo. Quiero ver hasta dónde puedes retirarte.",
  ui_story_5072_50721201_22_dialog_content = "Eso es un callejón sin salida. ¿Alguna vez has considerado la mala posición en la que te encuentras ahora?",
  ui_story_5072_50721201_23_dialog_content = "¿De verdad pensaste que era un callejón sin salida? Esto es más fácil de lo que pensaba, Anfitrión de Vilanor... No, debería llamarte el Vilanor.",
  ui_story_5072_50721201_24_dialog_content = "¡Apúrate, la señorita Arrie atrajo al Anfitrión de Vilanor allí arriba. ¡Cierra todas las salidas ahora!",
  ui_story_5072_50721201_25_dialog_content = "<color=#e8d9bb>Sonido metálico... ¡Wham!</color>",
  ui_story_5072_50721201_26_dialog_content = "¡¿Qué...?!",
  ui_story_5072_50721201_27_dialog_content = "Aquí es donde se detiene tu reinado de terror.",
  ui_story_5072_50721201_28_dialog_content = "No voy a pelear contigo aquí. ¡No puedes atraparme aquí! ¡Malditos sean todos!",
  ui_story_5072_50721201_29_dialog_content = "No te preocupes por ellos. Te lo dije, ¡estás peleando conmigo!",
  ui_story_5072_50721301_1_dialog_content = "Está bien, supongo que ninguno de nosotros puede ir a ninguna parte.",
  ui_story_5072_50721301_2_dialog_content = "¿Así que crees que este es mi final? ¡Me parece que este es tu lugar de descanso final!",
  ui_story_5072_50721301_3_dialog_content = "¡Toma esto!",
  ui_story_5072_50721301_4_dialog_content = "<color=#e8d9bb>¡Swoosh!</color>",
  ui_story_5072_50721301_5_dialog_content = "¿¡No aterrizó!?",
  ui_story_5072_50721301_6_dialog_content = "¿Crees que tienes espacio para correr en este lugar tan estrecho?",
  ui_story_5072_50721301_7_dialog_content = "<color=#e8d9bb>¡Swoosh!</color>",
  ui_story_5072_50721301_8_dialog_content = "...",
  ui_story_5072_50721301_9_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5072_50721301_10_dialog_content = "¡De ninguna manera!",
  ui_story_5072_50721301_11_dialog_content = "¡Imposible! Solo eres un sustituto, ¿cómo puedes trabajar tan bien con la Espada Mágica!",
  ui_story_5072_50721301_12_dialog_content = "¿Proxy? ¡No, esta espada y yo somos socios!",
  ui_story_5072_50721301_13_dialog_content = "¡Lo guío para golpear, y él me guía hacia mi destino!",
  ui_story_5072_50721301_14_dialog_content = "<color=#e8d9bb>Swoosh... ¡Clang!</color>",
  ui_story_5072_50721301_15_dialog_content = "¡¿Cómo es posible que tú puedas bloquear eso?!",
  ui_story_5072_50721301_16_dialog_content = "¡Mi turno!",
  ui_story_5072_50721301_17_dialog_content = "<color=#e8d9bb>¡Swoosh!</color>",
  ui_story_5072_50721301_18_dialog_content = "¡Oh, no!",
  ui_story_5072_50721301_19_dialog_content = "Entonces, este es tu plan, ya veo.",
  ui_story_5072_50721301_20_dialog_content = "Derríbame del baluarte y no habrá nadie a quien pueda poseer.",
  ui_story_5072_50721301_21_dialog_content = "...",
  ui_story_5072_50721301_22_dialog_content = "Je... ¡Jajaja!",
  ui_story_5072_50721301_23_dialog_content = "¿Qué es tan gracioso?",
  ui_story_5072_50721301_24_dialog_content = "Ignoraste un detalle importante.",
  ui_story_5072_50721301_25_dialog_content = "¡Tengo una marioneta perfectamente prescindible!",
  ui_story_5072_50721301_26_dialog_content = "¿Cómo vas a luchar si solo lo uso como un escudo humano? ¿Vas a matar a un hombre inocente con tu espada?",
  ui_story_5072_50721301_27_dialog_content = "Hmm, la señorita Armilla realmente es una genio para haber visto venir esto.",
  ui_story_5072_50721301_28_dialog_content = "Vaya. ¡Aquí viene el anzuelo!",
  ui_story_5072_50721301_29_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_5072_50721301_30_dialog_content = "¡¿Qué es esto?!",
  ui_story_5072_50721301_31_dialog_content = "Gancho de pivote y cadena, así que ya no puedes explotar el cuerpo del mortal atado.",
  ui_story_5072_50721301_32_dialog_content = "No... ¡Suéltame, ahora!",
  ui_story_5072_50721301_33_dialog_content = "Deja de retorcerte. El mejor artesano de Longzhou hizo esto. Cuanto más luchas, más apretado se pone.",
  ui_story_5072_50721301_34_dialog_content = "La Espada Mágica nació bajo la bendición de la luna.",
  ui_story_5072_50721301_35_dialog_content = "¡Por favor, bendígalo de nuevo para que pueda someter a este Vilanor!",
  ui_story_5072_50721302_1_dialog_content = "¡Este es el final!",
  ui_story_5072_50721302_2_dialog_content = "<color=#e8d9bb>¡Swoosh!</color>",
  ui_story_5072_50721302_3_dialog_content = "Aaaaaaaargh!!",
  ui_story_5072_50721302_4_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_5072_50721302_5_dialog_content = "¡La dama de Longzhou ganó!",
  ui_story_5072_50721302_6_dialog_content = "¡Rápidamente, sube y libera a la víctima de la espada maldita!",
  ui_story_5072_50721302_7_dialog_content = "Felicitaciones, mi señora. Misión cumplida.",
  ui_story_5072_50721302_8_dialog_content = "En ese caso, ya no soy la dama de Longzhou.",
  ui_story_5072_50721302_9_dialog_content = "¿Qué estás diciendo? Esa identidad e imagen es indeleble en la mente de todos ahora.",
  ui_story_5072_50721302_10_dialog_content = "Se ha convertido en una parte de ti, al igual que la Espada Mágica Arrie.",
  ui_story_5072_50721302_11_dialog_content = "¿Cómo está el tipo que fue poseído?",
  ui_story_5072_50721302_12_dialog_content = "Está bien. Evitaste los puntos vitales en todos tus ataques. Muy amable de tu parte.",
  ui_story_5072_50721302_13_dialog_content = "El mayor problema ahora es...",
  ui_story_5072_50721302_14_dialog_content = "Lo manejaré. Con el guante que me diste, señorita Armilla, no debería ser un problema.",
  ui_story_5072_50721302_15_dialog_content = "Pero el guante no suprimirá todos sus poderes, así que tan pronto como sientas que algo va mal, suéltalo inmediatamente, ¿de acuerdo?",
  ui_story_5072_50721302_16_dialog_content = "Sí. Lo tendré en mente...",
  ui_story_5072_50721302_17_dialog_content = "...",
  ui_story_5072_50721302_18_dialog_content = "(Odio, odio, odio...)",
  ui_story_5072_50721302_19_dialog_content = "(Matar, matar, matar...)",
  ui_story_5072_50721302_20_dialog_content = "<size=45>(Busco... venganza...!)</size>",
  ui_story_5072_50721302_21_dialog_content = "¡Oye, estás bien, Arrie?!",
  ui_story_5072_50721302_22_dialog_content = "Oh...",
  ui_story_5072_50721302_23_dialog_content = "No, tengo que alejar la espada maldita antes de que se apodere de Arrie!",
  ui_story_5072_50721302_24_dialog_content = "...",
  ui_story_5072_50721302_25_dialog_content = "¡Agh!",
  ui_story_5072_50721302_26_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5072_50721302_27_dialog_content = "El Vilanor... ¡Está volando por sí solo!",
  ui_story_5072_50721302_28_dialog_content = "...",
  ui_story_5072_50721302_29_dialog_content = "<color=#e8d9bb>¡Swoosh!</color>",
  ui_story_5072_50721302_30_dialog_content = "¡Bombardeo de campana, golpea!",
  ui_story_5072_50721302_31_dialog_content = "<color=#e8d9bb>¡Swoosh!</color>",
  ui_story_5072_50721302_32_dialog_content = "Esto debería hacerlo.",
  ui_story_5072_50721302_33_dialog_content = "¿Estás bien, Arrie?",
  ui_story_5072_50721401_1_dialog_content = "¡Háblame, Arrie!",
  ui_story_5072_50721401_2_dialog_content = "Estoy bien. Sin embargo...",
  ui_story_5072_50721401_3_dialog_content = "La espada se escapó una vez más por mi culpa.",
  ui_story_5072_50721401_4_dialog_content = "Si posee a otra persona...",
  ui_story_5072_50721401_5_dialog_content = "Tenemos que empezar desde el principio otra vez.",
  ui_story_5072_50721401_6_dialog_content = "Está bien, tenemos tiempo.",
  ui_story_5072_50721401_7_dialog_content = "El toque de queda del Gremio Umbraton está en vigor ahora, por lo que no hay nadie en la calle para ser el títere de Vilanor.",
  ui_story_5072_50721401_8_dialog_content = "Además, en el estado actual, probablemente se fue por instinto y no tiene ningún deseo de poseer a nadie.",
  ui_story_5072_50721401_9_dialog_content = "Así que tenemos que movernos ahora y localizarlo.",
  ui_story_5072_50721401_10_dialog_content = "Pero Twin Pavilions Bay es enorme... ¿Por dónde empezamos?",
  ui_story_5072_50721401_11_dialog_content = "Si no podemos encontrarlo antes del amanecer...",
  ui_story_5072_50721401_12_dialog_content = "Relájate, lo he marcado.",
  ui_story_5072_50721401_13_dialog_content = "¿Lo marcó?",
  ui_story_5072_50721401_14_dialog_content = "Si, pero esto.",
  ui_story_5072_50721401_15_dialog_content = "<color=#e8d9bb>Ding, ding...</color>",
  ui_story_5072_50721401_16_dialog_content = "¿Campana?",
  ui_story_5072_50721401_17_dialog_content = "Sí. Até uno a él antes de que volara.",
  ui_story_5072_50721401_18_dialog_content = "Todo está en silencio en la ciudad ahora, así que podemos seguir los tintineos hasta la espada.",
  ui_story_5072_50721401_19_dialog_content = "Ya veo. ¡Vamos entonces!",
  ui_story_5072_50721401_20_dialog_content = "Es urgente. ¿Deberíamos dividirnos?",
  ui_story_5072_50721401_21_dialog_content = "No, es un gran problema si nos posee a uno de nosotros.",
  ui_story_5072_50721401_22_dialog_content = "Juntos, podemos cuidarnos mutuamente, incluso cuando estamos abrumados por el odio de la espada.",
  ui_story_5072_50721401_23_dialog_content = "Ya veo. Oh, lo siento por subestimar la cruda emoción que proyectaba. No esperaba que fuera tan intenso.",
  ui_story_5072_50721401_24_dialog_content = "No es tu culpa, Arrie. Yo también fui un poco descuidado.",
  ui_story_5072_50721401_25_dialog_content = "Tu rostro mostraba agonía cuando sostenías la espada. ¿Qué sentiste?",
  ui_story_5072_50721401_26_dialog_content = "Desprecio abrumador, dolor, pánico...",
  ui_story_5072_50721401_27_dialog_content = "Parecía detestar tanto al mundo como a sus propios sufrimientos al extremo.",
  ui_story_5072_50721401_28_dialog_content = "Por eso seguía poseyendo a las personas y buscando venganza como si quisiera poner fin al odio sin límites...",
  ui_story_5072_50721401_29_dialog_content = "La sede ha descubierto que el dueño de la galera es un traficante del mercado negro que obtuvo la espada de los piratas.",
  ui_story_5072_50721401_30_dialog_content = "Sin embargo, el trauma de ser robado de casa engendró malicia y pervertió los antiguos poderes de la espada.",
  ui_story_5072_50721401_31_dialog_content = "Hasta que ascendió para convertirse en una espada maligna y maldijo las antigüedades circundantes, así como a los marineros que las transportaban.",
  ui_story_5072_50721401_32_dialog_content = "El Gremio de la Concha Roja, el coleccionista y el portador de la espada se vieron envueltos en su camino de venganza.",
  ui_story_5072_50721401_X32_dialog_content = "Si el trato y la avaricia no terminan, probablemente el rencor tampoco lo hará.",
  ui_story_5072_50721401_33_dialog_content = "Entonces, ¿lo que hacemos ahora no es guardarlo bajo llave?",
  ui_story_5072_50721401_34_dialog_content = "No. Tenemos que eliminar sus emociones negativas. La mejor manera de hacer eso es...",
  ui_story_5072_50721401_35_dialog_content = "Tráelo de vuelta a casa.",
  ui_story_5072_50721401_36_dialog_content = "<color=#e8d9bb>Ding Ding...</color>",
  ui_story_5072_50721401_37_dialog_content = "Claro como una campana... ¡Vamos, por aquí!",
  ui_story_5072_50721601_1_dialog_content = "El sonido viene de este barco.",
  ui_story_5072_50721601_2_dialog_content = "¿Vamos a entrar a ciegas?",
  ui_story_5072_50721601_3_dialog_content = "Sí. Creo que sé dónde estará.",
  ui_story_5072_50721601_4_dialog_content = "¿Notaste que este barco se ve diferente a los demás que vimos afuera?",
  ui_story_5072_50721601_5_dialog_content = "Parece simplemente otro barco en el río de oro, pero la cubierta en realidad es...",
  ui_story_5072_50721601_6_dialog_content = "Típico de un transatlántico Lin.",
  ui_story_5072_50721601_7_dialog_content = "El Vilanor lanzó una ilusión de un transatlántico sobre un carguero del Río Dorado.",
  ui_story_5072_50721601_8_dialog_content = "Este es el tipo de barco que quería tomar y volver a casa.",
  ui_story_5072_50721601_9_dialog_content = "Estamos en la bodega de carga principal.",
  ui_story_5072_50721601_10_dialog_content = "Escuché que el dueño de este barco trabaja para piratas y criminales, por eso necesitaba una gran bodega de carga...",
  ui_story_5072_50721601_11_dialog_content = "También extorsionaron dinero de protección de los barcos vecinos.",
  ui_story_5072_50721601_12_dialog_content = "Eso lo explicaría. Todo ese beneficio hinchado y la codicia maldijeron la espada.",
  ui_story_5072_50721601_13_dialog_content = "Me pregunto cuántas reliquias de Longzhou terminaron en Astra de esta manera y nunca volvieron a casa.",
  ui_story_5072_50721601_14_dialog_content = "Entonces, el Vilanor vino aquí con la esperanza de regresar a Longzhou en este barco...",
  ui_story_5072_50721601_15_dialog_content = "Correcto. De vuelta a su hogar y redescubrir su propósito.",
  ui_story_5072_50721601_16_dialog_content = "¿Espada mágica? Hace mucho tiempo que no sé de ti.",
  ui_story_5072_50721601_17_dialog_content = "¿Qué más puedes sentir de Vilanor?",
  ui_story_5072_50721601_18_dialog_content = "Debo decir, ha sido completamente corrompido por la avaricia para que yo pueda recoger mucho de cualquier otra cosa.",
  ui_story_5072_50721601_19_dialog_content = "Pero el anhelo de hogar y tratar de encontrar su propósito está ahí...",
  ui_story_5072_50721601_20_dialog_content = "Siguió esperando volver, solo para ser desplazado y adquirido como un coleccionable una y otra vez, hasta que se convirtió en una máquina de matar...",
  ui_story_5072_50721601_21_dialog_content = "La agonía, la miseria, la resignación.",
  ui_story_5072_50721601_22_dialog_content = "Si pasara por el mismo sufrimiento, también podría convertirme en malvado.",
  ui_story_5072_50721601_23_dialog_content = "¡De ninguna manera!",
  ui_story_5072_50721601_24_dialog_content = "¡Por supuesto que no, porque tengo al mejor dueño del mundo!",
  ui_story_5072_50721601_25_dialog_content = "¡...!",
  ui_story_5072_50721601_26_dialog_content = "Ten cuidado, Arrie, creo que nos ha visto.",
  ui_story_5072_50721601_27_dialog_content = "Y nos ve como enemigos.",
  ui_story_5072_50721601_28_dialog_content = "¿Hay alguna manera de calmarlo?",
  ui_story_5072_50721601_29_dialog_content = "Incluso si los hay, todavía tenemos que someterlos primero. Hagamos esto, Arrie.",
  ui_story_5072_50721601_30_dialog_content = "¡Seguro!",
  ui_story_5072_50721602_1_dialog_content = "¿Ya termino?",
  ui_story_5072_50721602_2_dialog_content = "No puede atacarnos en el corto plazo.",
  ui_story_5072_50721602_3_dialog_content = "Traje una caja de espadas conmigo para que no tengamos que tocarla...",
  ui_story_5072_50721602_4_dialog_content = "Está bien, tengo esto.",
  ui_story_5072_50721602_5_dialog_content = "Espera, no estás usando la mano desnuda, ¿verdad...",
  ui_story_5072_50721602_6_dialog_content = "...",
  ui_story_5072_50721602_7_dialog_content = "...",
  ui_story_5072_50721602_8_dialog_content = "Puff... Puff...",
  ui_story_5072_50721602_9_dialog_content = "Está bien. Está bien...",
  ui_story_5072_50721602_10_dialog_content = "Estamos aquí para rescatarte.",
  ui_story_5072_50721602_11_dialog_content = "Me complace que puedas ir a casa después de un viaje tan largo.",
  ui_story_5072_50721602_12_dialog_content = "Es un milagro.",
  ui_story_5072_50721602_13_dialog_content = "El Vilanor se está calmando.",
  ui_story_5072_50721602_14_dialog_content = "Supongo que la mentalidad de un portador realmente puede afectar a una espada... Ni siquiera los gadgets pueden lograr eso.",
  ui_story_5072_50721602_15_dialog_content = "Por favor, toma esta espada.",
  ui_story_5072_50721602_16_dialog_content = "Asegúrate de que vuelva a donde pertenece.",
  ui_story_5072_50721602_17_dialog_content = "Lo tienes.",
  ui_story_5072_50721602_18_dialog_content = "Oh...",
  ui_story_5072_50721602_19_dialog_content = "No quiere dejarte...",
  ui_story_5072_50721602_20_dialog_content = "Ya que nunca ha tenido un dueño que realmente se preocupe tanto como tú.",
  ui_story_5072_50721602_21_dialog_content = "Gracias por la oferta, pero no puedo ser tu dueño porque ya tengo una espada propia.",
  ui_story_5072_50721602_22_dialog_content = "¿Sin mencionar que todavía tienes un propósito que buscar?",
  ui_story_5072_50721602_23_dialog_content = "Espero que encuentres a alguien que realmente te aprecie en casa...",
  ui_story_5072_50721602_24_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_5072_50721602_25_dialog_content = "Llamaremos a esto la despedida final.",
  ui_story_5072_50721602_26_dialog_content = "Organizaré un barco para llevarlo de vuelta a Longzhou lo más pronto posible.",
  ui_story_5072_50721602_27_dialog_content = "Como tu paga...",
  ui_story_5072_50721602_28_dialog_content = "Eso no es importante ahora. Deberías continuar con tu plan para esta espada de inmediato.",
  ui_story_5072_50721602_29_dialog_content = "Estaba en fragmentos, pero obtuve una imagen bastante clara del pasado de la Espada Mágica.",
  ui_story_5072_50721602_30_dialog_content = "Oponerme a las \"maldiciones\" ya no es un problema para mí, siempre y cuando tenga la espada conmigo.",
  ui_story_5072_50721602_31_dialog_content = "Te debo eso, señorita Armilla.",
  ui_story_5072_50721602_32_dialog_content = "Pero no hice nada. Sin embargo, siéntete libre de verme en cualquier momento para obtener las últimas noticias sobre Longzhou.",
  ui_story_5072_50721602_33_dialog_content = "De todos modos, ven a verme cuando estés buscando gadgets o atuendos personalizados de Longzhou también.",
  ui_story_5072_50721602_34_dialog_content = "Entiendo.",
  ui_story_5072_50721602_35_dialog_content = "¡Hasta la próxima!",
  ui_story_5072_50721602_36_dialog_content = "Hasta la próxima.",
  ui_story_5072_50721602_37_dialog_content = "Lo hiciste genial, Espada mágica.",
  ui_story_5072_50721602_38_dialog_content = "Si esa espada tuviera un deseo, tú también debes tener uno, ¿verdad?",
  ui_story_5072_50721602_39_dialog_content = "¿Hay algún lugar al que quieras ir? ¿Debería llevarte de vuelta a donde mis padres te encontraron?",
  ui_story_5072_50721602_40_dialog_content = "Noté que estabas algo reacio cuando entregaste esa espada.",
  ui_story_5072_50721602_41_dialog_content = "¿Cruzó por tu mente la idea de reemplazarme?",
  ui_story_5072_50721602_42_dialog_content = "¿Qué? ¡No, nunca! ¡Eso no es lo que estaba pensando!",
  ui_story_5072_50721602_43_dialog_content = "Lo sé, lo sé... Solo estoy bromeando contigo, Arrie.",
  ui_story_5072_50721602_44_dialog_content = "Todos nacieron en algún lugar y viajarán a muchos lugares importantes en la vida.",
  ui_story_5072_50721602_45_dialog_content = "Pero por ahora, quedarme contigo es el deseo de la espada... eh, mi único deseo.",
  ui_story_5072_50721602_46_dialog_content = "¿Es cierto? ¿Estás seguro?",
  ui_story_5072_50721602_47_dialog_content = "Por supuesto. Como mi dueño, espero que tengas más fe en ti mismo.",
  ui_story_5072_50721602_48_dialog_content = "Es inmutable que fuiste elegido por el destino para sufrir las desgracias que tienes...",
  ui_story_5072_50721602_49_dialog_content = "El hecho de que nací para protegerte también es inmutable.",
  ui_story_5072_50721602_50_dialog_content = "Estaré miserable si no puedo estar contigo y compartir tus cargas.",
  ui_story_5072_50721602_51_dialog_content = "¡Por favor, déjame quedarme para no volverse malvado y lleno de rencor!",
  ui_story_5072_50721602_52_dialog_content = "Vale, vale. ¡Permíteme agradecerte de antemano por toda la ayuda futura entonces!",
  ui_story_5072_50721602_53_dialog_content = "Ya es de mañana.",
  ui_story_5072_50721602_54_dialog_content = "Es un día perfecto para que una dama vaya de compras... Espera, ya no soy una socialité.",
  ui_story_5072_50721602_X54_dialog_content = "Como el Espadachín de la Espada Mágica... o simplemente como yo mismo.",
  ui_story_5072_50721602_55_dialog_content = "Tengo un futuro por delante... y también la Espada Mágica.",
  ui_story_5072_50721602_56_dialog_content = "Oye, es hora de terminar tu historia, adivino.",
  ui_story_5072_50721602_57_dialog_content = "No tienes que decir eso de nuevo.",
  ui_story_5072_50721602_58_dialog_content = "Pero, ¿dónde está el tipo irritado para quien hice una lectura? No lo veo hoy.",
  ui_story_5072_50721602_59_dialog_content = "Bueno, esto es lo que pasó...",
  ui_story_5072_50721602_60_dialog_content = "La pequeña ganancia que obtuvo fue de tratar con antigüedades del mercado negro.",
  ui_story_5072_50721602_X60_dialog_content = "La sede está investigando eso en este momento y ha confiscado los envíos.",
  ui_story_5072_50721602_61_dialog_content = "Perdió todo su dinero y probablemente está haciendo una rabieta en este momento.",
  ui_story_5072_50721602_62_dialog_content = "Ya veo. Parece que el hombre realmente está pasando por un mal momento ahora.",
  ui_story_5072_50721602_63_dialog_content = "Lo que va, vuelve. Tienes que tener cuidado incluso cuando estás en tu punto más alto.",
  ui_story_5072_50721602_64_dialog_content = "O no tendrás a dónde ir sino hacia abajo cuando las tornas cambien.",
  ui_story_5072_50721602_65_dialog_content = "¡Disfruta..!",
  ui_story_5072_50721602_66_dialog_content = "¡En la desgracia de otros...!",
  ui_story_5072_50721602_67_dialog_content = "¡Olvídate de ese infeliz y termina tu historia!",
  ui_story_5072_50721602_68_dialog_content = "Claro. Retomando donde lo dejamos, el espadachín llegó a Twin Pavilions Bay.",
  ui_story_5072_50721602_69_dialog_content = "En una tarea asignada por un artesano extranjero para deshacerse de esa espada maldita que controla la mente.",
  ui_story_5072_50721602_70_dialog_content = "El espadachín encontró, luchó y acorraló a la espada maldita.",
  ui_story_5072_50721602_X70_dialog_content = "Solo para que la espada maldita resuene con su propia espada mágica.",
  ui_story_5072_50721602_71_dialog_content = "Lo que casi atrapó al espadachín bajo su hechizo.",
  ui_story_5072_50721602_72_dialog_content = "Afortunadamente, su espada mágica intervino en el momento crucial y le mostró su propia historia para romper el control.",
  ui_story_5072_50721602_X72_dialog_content = "El espadachín entonces desafió a la espada maldita a un duelo bajo una luna llena.",
  ui_story_5072_50721602_X73_dialog_content = "Bajo la luz de la luna llena, en lo alto de la muralla de Twin Pavilions Bay, lucharon en una batalla pareja...",
  ui_story_5072_50721602_73_dialog_content = "¡Vamos, dinos quién ganó!",
  ui_story_5072_50721602_74_dialog_content = "¿Crees que estaríamos disfrutando todo esto si la espada maldita hubiera ganado?",
  ui_story_5072_50721602_75_dialog_content = "Bueno...",
  ui_story_5072_50721602_76_dialog_content = "Como dijeron...",
  ui_story_5072_50721602_77_dialog_content = "Trata a una espada como tratas a una persona y la espada te devolverá lo mismo.",
  ui_story_5072_50721602_78_dialog_content = "En los sueños, lo imposible es posible. Las espinas pueden florecer, la espada puede hablar.",
  ui_story_5072_50721602_79_dialog_content = "La espada habla lo que está en tu mente, ¡no olvides lo que escuchaste en tus sueños!",
  ui_story_5072_50721602_80_dialog_content = "Todo lo que haces es mantenernos en suspenso. ¡Vamos a salir de aquí!",
  ui_story_5072_50721602_81_dialog_content = "Es hora de que yo también me vaya.",
  ui_story_5072_50721602_82_dialog_content = "Dulces sueños a todos. ¡Nos vemos la próxima vez!",
  ui_story_5072_50721701_1_dialog_content = "¡Alto! Esta es una nave privada. ¡Nadie entra sin autorización!",
  ui_story_5072_50721701_2_dialog_content = "Bueno, un sirviente lo está vigilando. Entonces, hasta la próxima vez.",
  ui_story_5072_50721702_1_dialog_content = "¡Alto! Esta es una nave privada. ¡Nadie entra sin autorización!",
  ui_story_5072_50721702_2_dialog_content = "Tengo una orden de los Lins y del Gremio Umbraton. Este lugar está albergando a un criminal y debemos registrar las inmediaciones!",
  ui_story_5072_50721702_3_dialog_content = "¿Orden de arresto? ¡Negocios oficiales genuinos, veo! ¡Me voy de aquí!"
}
return config
